window.QUIZ_INTANGIBLE = (window.QUIZ_INTANGIBLE||[]).concat([{"q":"○○○○○는 마을의 평안과 풍어를 기원하는 굿으로, 부안군 위도면 대리 마을에서 매년 1월초에 열린다. ○○○○는 바닷가에서 용왕굿을 할 때 띠배를 띄워 보내기 때문에 ○○○○라 부르게 되었고, 소원을 빌기 위해 세운 집인 원당에서 굿을 하기 때문에 원당제라고도 한다. 띠배는 띠풀과 짚, 싸리나무 등을 함께 엮어 길이 3m, 폭 2m 정도의 크기로 만드는데 안에는 각종 제물과 함께 7개의 허수아비, 돗대, 닻을 만들어 달아 배형태를 갖춘다. 놀이는 수호신을 모신 원당에 올라가 제물을 차리고 굿을 한 후 마을로 내려와 마을의 산을 돌고 바닷가에서 용왕굿을 함으로써, 굿…","a":"위도띠뱃놀이","c":"국가무형유산","r":"전북특별자치도","s":"부안군","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623782.jpg"},{"q":"산조는 남부지역의 무속음악에서 발생한 독주곡 형태의 음악이다. 산조는 남도 무속음악과관련이 있는 시나위 혹은 심방곡・봉장취 같은 기악합주곡이 독주악기로 연주되면서 기교가 확대되었고, 판소리 가락을 도입하면서 틀이 잡혔다. 아쟁은 악기 제작 재료로 분류하는 방법인 팔음(八音)에 의하면 사부악기, 음악의 계통에 의한 분류 방법으로는 당악기로 분류한다. 소리는 깊고 장엄하며 저음악기로서 매우 중요한 구실을 한다. 2009년 3월 5일에 박종선이 보유자로 인정받아 활동해 오다가 2024년 3월 20일 사망하였다. 박종선 보유자의 제자 김영길이 2026년 새로운 보유자로 인정…","a":"아쟁산조","c":"시도무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018102609361000.jpg"},{"q":"금산 ○○○○는 금산 김녕김씨 집안에 전해오는 전통적인 술 제조법으로 술을 만드는 방법은 김씨 문중에 내려오는 『잡록』에 기록되어 있다. 이에 의하면 잘게 부순 통밀과 인삼을 섞어 3개월간 발효시켜 누룩을 만든다. 쌀로 고두밥을 짓고 준비해 두었던 누룩과 인삼을 섞어 밑술을 만든다. 여기에 다시 약쑥·솔잎·인삼·고두밥을 섞어 40~60일간 숙성시킨다. 술이 다 익으면 거르고 고리를 써서 증류한다. 알콜 농도는 43% 정도이며, 인삼향기가 나며 빛깔이 부드럽다. 기능보유자인 김창수씨는 김문기의 18대손으로 조모와 모친으로부터 그 기술을 전수받아 계승해오고 있다.","a":"금산인삼백주","c":"시도무형유산","r":"충청남도","s":"금산군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643993.jpg"},{"q":"‘○○○○’은 전북 남원시 금지면 옹정리 일원에서 전승되는 농악으로 호남 좌도농악의 성격과 특징을 지니고 있다. ○○○○은 들당산굿, 마당밟이, 판굿으로 구성된 마을굿 특징과 더불어 걸립굿의 성격이 반영되어 있다. 특히 판굿의 뒷굿(도둑잽이, 재능기) 구성이 특이하며 호남 좌도농악에서만 사용하는 부들상모를 전승자들이 현재에도 직접 제작하여 연행하고 있다.","a":"남원농악","c":"국가무형유산","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/2019090314092400.jpg"},{"q":"○○○○○는 정월 대보름을 전후하여 안동지방에서 행해지던 민속놀이의 하나로 동채싸움이라고도 부른다. 유래에 대한 정확한 기록은 없으나 후백제의 견훤과 고려 태조 왕건의 싸움에서 비롯되었다는 설이 전해진다. 이 놀이를 위해 연말이면 안동 근처에서 적당한 나무를 미리 골라 두었다가 산신에게 고사를 지내고 나무를 베어 운반한다. 동채의 크기나 견고성이 싸움의 승패를 결정하는데 영향을 주기 때문에 동채를 만들 때는 사람들이 보지 못하도록 대문을 잠그고 만든다. 마을을 동서로 나누어 편을 가르는데 거주지가 아닌 태어난 곳을 위주로 편을 나누기 때문에 때로는 부부간에도 편이 다…","a":"안동차전놀이","c":"국가무형유산","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623986.jpg"},{"q":"○○○는 49재(사람이 죽은지 49일째 되는 날에 지내는 제사)의 한 형태로, 영혼이 불교를 믿고 의지함으로써 극락왕생하게 하는 의식이다. 석가가 영취산에서 행한 설법회상인 영산회상을 오늘날에 재현한다는 상징적인 의미를 지니고 있다. ○○○는 불교 천도의례 중 대표적인 제사로 ‘영산작법’이라고도 한다. 기원은 분명하지 않으나, 이능화의 『조선불교통사』에 의하면 조선 전기에 이미 행해지고 있었다. ○○○는 제단이 만들어지는 곳을 상징화하기 위해 야외에 영산회상도를 내다 거는 것으로 시작한다. 신앙의 대상을 절 밖에서 모셔오는 행렬의식을 하는데, 이때 부처의 공덕을 찬양…","a":"영산재","c":"국가무형유산","r":"서울특별시","s":"서대문구","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623255.jpg"},{"q":"○○○은 금과 은을 녹여 아름다운 장신구를 만들어 내는 장인을 말한다. 삼국시대 이래 금은 세공기술이 크게 발달되었으며 고려시대에는 청동에까지 이 기법을 적용하여 뛰어난 유물을 남기기도 했다. 금은 세공은 950℃의 높은 열로 금과 은을 단련하는 작업이다. 은이 식고 단단해지면 다시 가열해 부드럽게 만든 뒤 망치질을 한다. 필요한 두께의 은이 만들어지면 원하는 디자인의 작품을 만들었다. 은은 밝은 회색 빛깔이지만, 약품처리를 하면 다양한 색상을 만들어 낼 수 있다. 여기에 금박 등으로 장식하면 전혀 새로운 매력을 발산한다. 보유자 이효준은 1988년부터 고양시 화전동…","a":"금은장","c":"시도무형유산","r":"경기도","s":"고양시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018091411264600.jpg"},{"q":"○○○은 법사 또는 보살이 집안의 평안과 환자 치료 등을 위해, 앉아서 스스로 북과 징을 치며 독경을 하는 것[坐經]을 말한다. 설위설경은 위목을 설치[設位]하고 경문을 읽는다[說經]는 뜻으로 법사의 독경 의례를 더욱 구체적으로 표현한 것이다. 예로부터 태안 지역에서 독경을 하는 법사들은 옥추경[玉樞經], 팔양경[八陽經], 칠성연명경[七星延命經], 지신다라니경[地神陀羅尼經]을 4대 경문이라 하여 의례에 쓰이는 가장 중요한 경문으로 꼽고 있다. 천존, 칠성, 산신, 용왕을 주요 신령으로, 조왕, 성주, 지신, 삼신을 가택사신으로 위하고 있다. 독경은 소원을 빌기 원하는…","a":"앉은굿(태안설위설경)","c":"시도무형유산","r":"충청남도","s":"태안군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2024061116053800.jpg"},{"q":"매듭은 농경사회가 시작되면서 넝쿨, 식물의 줄기 등을 이용하여 인간생활에 편리한 동아줄, 끈, 등을 만들어 사용하면서 유래되었으며, 줄이나 끈을 이용하여 물건을 보관, 운반하고 생활에 필요한 도구를 제작하여 사용하였고 멋과 색상, 아름다움이 가미되면서 의상이나 몸치장에 이용되어 왔다. 매듭이나 다회에 대한 기원은 신석기시대의 승문토기(새끼무늬 토기)에서 이미 찾을 수 있으나, 섬유가 갖는 특수한 결정인 습도, 온도에 따라 오랜기간의 보존이 어려울 뿐만 아니라 대부분이 손으로 매듭을 맺어야 된다는 점을 감안할 때 섬유의 마모를 초래하게 되어 근래의 것 이외에는 거의 전…","a":"매듭장","c":"시도무형유산","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644638.jpg"},{"q":"○○은 판소리의 북 반주의 법례를 의미한다. 고수는 진양조, 중모리, 중중모리, 자진모리, 휘모리, 엇모리, 엇중모리 등의 다양한 장단을 치면서 소리꾼의 노래를 반주한다. 또한, 추임새를 통해 소리꾼의 흥을 돋우면서 소리판을 이끌어가기도 한다. 판소리에는 예로부터‘일고수 이명창’과 같이 고수의 중요성을 강조하고 있다.","a":"고법(북·장구)","c":"시도무형유산","r":"인천광역시","s":"서해구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2016010414532400.jpg"},{"q":"◦ 궁시장이란 활과 화살을 만드는 기능과 그 기능을 지닌 사람을 일컫는 말로 활을 만드는 사람을 궁장(弓匠), 화살을 만드는 사람을 시장(矢匠)이라 칭한다. ◦ 주장응은 故김장환(국가무형유산 보유자)과의 인연으로 1973년 겨울 농한기에 김장환의 부천 공방에 가서 각궁 제조기술을 배우고 난 뒤 부천으로 이사하며 본격적으로 제궁기술을 연마하였다. 이후 1979년 충청남도 당진의 활터인 학유정(鶴遊亭)에 공방을 열고 각궁(角弓)을 제작하였다. 1982년 관운장이 있는 연기군 ○○면(現 세종특별자치시 ○○면)으로 이주 한 후 1990년 무렵 ‘국궁제작소’라는 이름의 공방을…","a":"전의 궁인","c":"시도무형유산","r":"세종특별자치시","s":null,"i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2023050111142400.JPG"},{"q":"○○○○○은 경상남도 거제도를 중심으로 통영시 일대의 어촌과 한산도, 사량도, 욕지도, 갈도, 죽도 등지에서 벌어지는 공동제의로 무당의 노래가 뛰어나고 반주악기에 북이 첨가되는 것이 특징이다. 동○○○○○과 달리 진행과정에서 무당이 악사와 주고받는 재담이 극히 드물고 사설이 없으며 굿이 진지하다. 굿 중간에 북을 치는 고수와 이를 지켜보는 마을사람들이 함께 놀이마당을 이루기도 한다. 굿은 틀맞이, 당산굿, 일월맞이굿, 용왕굿, 부정굿, 가망굿, 제석굿, 서낭굿, 댓굿, 손굿, 염불굿, 군웅굿, 거리굿으로 진행되며, 춤은 비교적 단조롭고 소박하며 혼자 추는 독무가 많다…","a":"남해안별신굿","c":"국가무형유산","r":"경상남도","s":"통영시","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1624168.jpg"},{"q":"○○○은 나무로 짠 가구나 기물 위에 무늬가 아름다운 전복이나 조개껍질을 갈고 문양을 오려서 옻칠로 붙이는 기술이다. 나전칠기의 제작과정은, 나무로 기본 틀인 백골을 짜고 그 표면을 사포로 문지르거나 틈새를 메워 고르게 한 다음 자개를 붙인다. 그 후 연마, 옻칠, 광내기 과정을 거쳐 완성한다. 자개로 무늬를 만드는 방법에는 자개를 실처럼 잘게 자른 '상사'로 기하학적인 문양을 만드는 끊음질 기법과, 자개를 문질러 얇게 만들어 국화, 대나무, 거북이 등 각종 도안 문양을 만드는 줄음질 기법이 있다. 나전 무늬는 고려시대와 조선 전기에는 모란·국화·연꽃 등의 식물무늬가…","a":"나전장","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1624274.jpg"},{"q":"○○○○○은 직접 가야금을 타면서 노래부르는 것을 가리킨다. 단가나 판소리 중 한 대목을 따다가 가야금 반주를 얹어 부르며, 판소리에서는 석화제라고도 한다. 조선 후기에 가야금산조의 명인 김창조가 부르기 시작하였다는 설이 있다. 장단에는 진양, 중모리, 중중모리, 자진모리 등이 쓰이고 있다. 가야금과 노래의 선율이 동일한 것이 원칙이나 노래를 가야금에 맞도록 변화시키기도 하고, 노래의 공간을 가야금 선율로 메우기도 하며, 가야금 간주를 가끔 넣어서 흥을 돋우기도 한다. 대표적인 곡으로는 녹음방초, 호남가, 청석령지나갈제, 죽장망혜, 춘향가 중 사랑가, 흥보가 중 제비…","a":"가야금병창","c":"시도무형유산","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644360.jpg"},{"q":"장도를 만드는 기능과 그 기능을 가진 사람을 ○○○이라 한다. 장도는 몸에 지니는 자그마한 칼로 일상생활이나 호신용 또는 장신구로 사용되었다. 고려시대부터 성인 남녀들이 호신용으로 지니고 다녔으며, 특히 조선시대에는 임진왜란 이후부터 사대부 양반 가문의 부녀자들이 순결을 지키기 위하여 필수적으로 휴대했다. 조선 후기부터는 장도가 몸단장을 하는 노리개로서 일종의 사치품이었기 때문에 제작과정이 정교하게 발달하였다. 장도 중에서 몸에 차는 것을 패도(佩刀)라 하고, 주머니 속에 넣는 것을 낭도(囊刀)라고 한다. 장도는 모양과 재료에 따라 여러 종류가 있다. 칼집장식이 복잡…","a":"장도장","c":"국가무형유산","r":"전남광주통합특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623885.jpg"},{"q":"○○○는 과하주라고도 한다. 건강증진을 위한 술로 첨가하는 약재와 지역에 따라 독특한 맛과 향을 살린 우리조상들의 지혜가 담긴 전통 민속주이다. 일제의 주세법과 개발시대의 편협한 논리로 대부분의 우수한 전통주가 사라지고 말았다. ○○○도 예외일 수 없었다. 하지만, 우리문화의 한 요소인 전통주를 찾고 지키고 키워나가는 일은 시급한 일이 아닐 수 없다. ‘○○○○○’는 ○○군 회천면 지역을 기반으로 전승되어온 전통주로 향과 맛이 진하고 숙취가 없으며, 마실 때 부드럽고 뒷맛이 개운하다. 재료로 밀, 보리, 멥쌀, 찹쌀 등 주곡(主穀)이 다 들어가는 술로 전국적으로도 유…","a":"보성 강하주","c":"시도무형유산","r":"전남광주통합특별시","s":"보성군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644242.jpg"},{"q":"○○○○○는 전북특별자치도 익산 지방에서 전승되는 현악영산회상이라는 기악곡이다. 관악영산회상과 평조회상의 대칭으로 불리는 음악으로, 이들과는 조(調)와 악기 편성이 다르다. ○○○○○는 거문고, 가야금, 양금, 단소, 해금, 대금, 피리, 장구 등 여덟 가지 악기로 연주한다. 곡목은 다스름부터 시작해 본령산, 중령산, 세령산, 가락덜이, 상현도드리, 세환입, 하현도드리, 염불도드리타령, 군악, 계면가락도드리, 양청도드리, 우조가락도드리, 풍류굿거리까지 총 15곡이다.","a":"이리향제줄풍류","c":"국가무형유산","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623791.jpg"},{"q":"친정이 서천으로 파평윤씨인 윤자덕은 25세에 은진송씨가로 시집오면서부터 대전에 거주해왔다. 시집은 동춘당 송준길의 둘째손자 송병하(1642~1697)의 12대 종손가이다. 맏며느리인 그는 시어머니로부터 종가의 제례 등 대소사에 소용된 각종 음식기능을 전수 받았다. 집안에 전해오는 『주식시의(酒食是儀)』와『우음제방(禹飮諸方)』이란 필사본의 요리서에는 ○○○를 비롯한 각종 가양주의 제조법이 실려있다. ○○○는 밑술용으로 누룩가루 1되, 멥쌀 3되를 사용하며, 덧술용으로 찹쌀 1말, 송순 500g의 재료가 사용된다. 과정을 보면 먼저 멥쌀가루로 흰무리를 찐 다음 누룩가루와…","a":"송순주","c":"시도무형유산","r":"대전광역시","s":"대덕구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643579.jpg"},{"q":"○○○○는 우리나라 전국 각지에서 전해져 온 풍속이다. 많은 사람들이 집단적으로 모여서 개천 위에 놓인 다리를 밟는 일종의 세시적인 대동행사지만 그 내용은 놀이성이 강하게 작용하므로 이를 답교놀이라고도 부른다. 일년 중 정월 대보름날 밤에 행해지는데 사람들은 이때 다리를 밟으면 일년 내내 다리병[脚氣病]을 앓지 않는다고 믿었다. 1970년 정월 대보름에는 장충동에 있는 ○○○에서 ○○○○ 행사가 복원되어 전승의 맥을 되찾게 되었다. 2009년 3월 5일에 서울시무형유산 종목으로 지정되었으며, 소리 분야의 박종국과 춤 분야의 조춘선이 2011년 1월 6일에 보유자로 인…","a":"수표교 다리밟기","c":"시도무형유산","r":"서울특별시","s":"금천구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018102409252900.jpg"},{"q":"꽃은 오래전부터 종교의식에서 널리 쓰여왔으며, 불교의 연꽃이나 도교에서 꽃은 생명의 창조와 재생의 의미로 여기졌으며, 무속의례에서도 만신이 화관을 쓰고 신의 위엄을 나타낸다. ○○○에서 쓰는 화관(花冠)은 꽃으로 장식된 모자로 이와같은 모자는 통일신라시대 때부터 궁중에서 사용되었으며, 고려시대에는 귀족과 양반계급의 부녀자들이 예복과 함께 꽃관을 썼다. 그 후 조선 영·정조때에 지나친 사치를 막기위해 화관이나 족두리를 쓰게 하였으나, 그 장식은 갖은 보석을 장식하여 매우 화려하였다고 전해지며, 오늘날의 ○○○는 전문적인 무용가에 의해 행위예술로 승화되어졌다. 황해도(민…","a":"화관무","c":"이북5도 무형유산","r":"황해도","s":"전역","i":"http://www.khs.go.kr/unisearch/images/nondesignated_cult_prop/2669397.jpg"},{"q":"\"○○○○○는 영산강 상류의 너른 들판 한가운데 자리잡고 있는 전형적인 농촌마을이다. 들판이 넓고 물산이 풍부한 곳답게 예술적 전통이 남달랐던 마을로 논농사를 지으면서 부르던 ○○○가 전승되고 있다. ○○ 황금○○○는 모판을 만드는 일부터 모를 찌고, 모를 심고, 논을 매고, 장원질을 하는 전 과정에 걸쳐 있다. 그리고 각각의 노래는 늦은 소리와 잦은 소리로 구성되어 있고, 특히 논매기에서는 <지화자소리>, <떨아지소리>, <나헤소리>, <사뒤여소리> 등과 같은 다양한 노래들이 배치돼 있다. 이런 구성과 짜임새는 황금○○○가 남도 민속예술의 멋과 신명을 담아 전승되어…","a":"담양 황금리 들노래","c":"시도무형유산","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644246.jpg"},{"q":"○○○○○은 어업을 위주로 하는 정포마을과 농업을 위주로 하는 대정마을 주민들이 농사가 잘 되고, 고기를 많이 잡게 해달라는 등의 마을 번영을 기원하는 도당굿의 하나이다. ○○○은 임경업 장군을 모시는 대표적인 서해안 풍어제이다. 최영 장군처럼 억울하게 죽은 영웅이 무속신이 되었듯이 임장군도 무속신이 되어 복수 하러 중국으로 가면서 연평도에서 조기를 잡아 선원을 배불리 먹였다는 전설과 함께 조기잡이 신으로 모시고 있다. ○○○○○은 2년이나 3년마다 음력 2월 초에 3일간 하는 것이 전례이지만, 마을 사정에 따라 더 자주하거나 늦춰지기도 하였다고 한다. 다른 풍어제에…","a":"강화 외포리 곶창굿","c":"시도무형유산","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643504.jpg"},{"q":"만가는 민요의 하나로 상여꾼들이 상여를 매고 가면서 부르는 상여소리다. ○○○○에는 두 종류가 있는데, 하나는 부자나 지역에서 양반가로 알려진 집에서 초상이 났을 때 신청의 예인들을 불러 그들에게 만가를 부르게 하는 것이다. 또 하나는 마을의 상여 설소리꾼에게 상여소리를 하게 하는 경우다. 신청의 예인들은 무당에 종사하는 사람들로, 상여가 나갈 때 북, 장구, 쇠, 피리 등을 연주하며 만가를 부르는데, 사설과 가락이 다양하고 무당의 노래를 응용하여 부르는 경우도 많다. 마을 상여소리꾼이 만가를 부르는 경우에는 조금 단순하여 에-소리나 가난보살만을 부른다. ○○○○는…","a":"진도만가","c":"시도무형유산","r":"전남광주통합특별시","s":"진도군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644203.jpg"},{"q":"○○○이란 우리나라 전통 배인 한선(韓船)을 만드는 장인을 말한다. 근대 한선이라고 하면 일제강점기(1910)을 전후로 강이나 바다에 떠다니던 배를 말하는데 거룻배, 나룻배, 야거리배, 당두리 등이 있었다. 현재 만들어지는 배는 주로 황포돛배, 놀이배, 기관선, 메생이(그물배나 낚시배) 등이다. 배를 만들 때는 대개 마을 사람들이 함께 일하며, 큰 배는 2∼3명, 작은 배는 1∼2명이 배의 종류에 따라 일주일에서 한 달에 걸쳐 만들어진다. 조선배의 특징은 물 깊이가 무릎밖에 안되는 강 상류를 오르내릴 수 있도록 배 밑바닥이 넓고 평평하며 탄력있게 만들어지는 점이다.…","a":"조선장","c":"시도무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643378.jpg"},{"q":"임실 ○○○○은 필봉리에 전승되고 있는 농악으로 호남좌도농악에 속한다. 필봉마을에는 예로부터 당산굿·마당밟기 정도의 단순한 농악이 전승되어 왔는데, 오늘날과 같은 높은 수준이 된 것은 1920년경에 상쇠(패의 지도자 격으로 꽹과리를 가장 잘 치는 사람) 박학삼을 마을로 초빙하여 그의 농악을 배우면서부터라고 한다. ○○○○의 농악수들은 흰 바지저고리에 남색조끼를 입고 삼색띠를 두르는데, 쇠잡이(꽹과리나 징을 치는 사람)만 상모(털이나 줄이 달린 농악에서 쓰는 모자)를 쓰며 나머지는 고깔을 쓴다. 농기, 용기(그릇), 영기(깃발), 긴 쇠나발, 사물(꽹과리, 징, 북,…","a":"임실필봉농악","c":"국가무형유산","r":"전북특별자치도","s":"임실군","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623766.jpg"},{"q":"침선이란 바늘에 실을 꿰어 꿰맴을 말하는 것으로 복식의 전반이라 할 수 있다. 복식이란 의복과 장식을 총칭하므로 그 범위는 바늘에 실을 꿰어 바느질로써 만들 수 있는 모든 것을 포함한다. 이러한 침선기술과 그 기능을 가진 사람을 ○○○이라 한다. 사람이 바느질을 시작한 것은 역사 이전부터였다고 한다. 지금의 바늘과 흡사한 신라시대 금속제가 발굴되었고, 삼국시대에 이미 상당한 수준의 침선이 고구려 벽화나 『삼국사기』를 통해 잘 나타나 있다. 고려시대와 조선시대로 이어지면서 더욱 발달되어 오늘날까지 전승되고 있다. 침선에 필요한 용구로는 옷감, 바늘, 실, 실패, 골무,…","a":"침선장","c":"시도무형유산","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643385.jpg"},{"q":"○○○역에 전승되는 민속놀이의 하나로 지신을 진정시키고, 잡귀를 물리치는 민간신앙적 마을굿의 한 형태이다. ○○○○는 옛부터 정월 대보름에 행해지던 일종의 가면행렬놀이로서 마을과 집안의 평안을 빌고 나아가서는 한해의 풍년을 기원하는 종교성을 띤다. 현재의 ○○○○○는 조선 후기에 행해지던 것을 원형으로 재구성하여 1970년 경부터 민속놀이로 다듬은 것이다. ○○○○○는 음력 12월에 악기, 의상, 도구 등을 준비하며 조선시대 각 계층의 신분인 사대부, 포수, 하동, 각시 등 35명 내외의 인원을 구성하여 놀이연습을 한다. 사대부는 총지휘자격이고, 하동과 포수는 상대역…","a":"동래지신밟기","c":"시도무형유산","r":"부산광역시","s":"동래구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643409.jpg"},{"q":"○○○○○는 달성군 하빈면 대평리 일대에 전승되고 있는 소리이다. ○○○는 예전부터 농사일이나 잡역노동을 할 때에 일의 고달픔을 달래고 작업의 능률을 올리는 기능을 하면서 오랫동안 전승하여 왔다. 모를 심고, 호미로 김을 매던 시대에 부르던 농업노동요는 농경방식이 변화하면서 차츰 쇠퇴하였으나 오랜 세월 전승되던 이 ○○○는 놀음놀이나 잔치 때에 불리면서 그 맥을 이어왔다. ○○○○○는 모찌기소리 등을 비롯하여 모두 10곡으로 구성되어 있다. 기능요로서의 현장성과 지역성을 나타내고 있는 이 소리는 영남지역 메나리조의 선율형태를 그대로 지니고 있다.","a":"달성하빈들소리","c":"시도무형유산","r":"대구광역시","s":"달성군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643491.jpg"},{"q":"○○○○은 소백산맥과 노령산맥 사이에 발달된 산악분지 형 민속 문화의 원형을 간직하고 있는 농악으로 좌도농악의 원형을 잘 보존하고 있다. ○○○○은 마을농악의 단계에서 벗어나 좀 더 발전하여 걸립농악의 단계를 거쳐 포장걸립농악으로 발전한 매우 전문적인 농악의 형태로 구축된 농악이다. ○○○○은 해방이후 전국에서 열린 각종 경연대회에 도 대표로 참여하여 수차례 수상하였으며 전국을 순회하며 활동한 ○○○○단 최상근 일행의 판굿이 발전하여 오늘날 ○○○○에 뿌리를 두고 전승되고 있다. ○○○○은 마을굿, 송계대방놀이, 두레풍장, 천내배걸립굿 등 금산의 기층문화에 다양한 발…","a":"금산농악","c":"시도무형유산","r":"충청남도","s":"금산군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2020060409522000.jpg"},{"q":"‘○○’(製茶)는 차나무의 싹, 잎, 어린줄기를 찌거나 덖거나 발효 등을 거쳐 재료로 만든 후 비비기, 찧기, 압착, 건조 등의 공정을 통해 마실 수 있는 차(茶)로 만드는 전통기술을 말한다. ○○에 관한 기록은 삼국시대부터 조선후기 다서(茶書)에 이르기까지 나타난다. ○○ 기법은 오랜 기간 동안 다양하게 변화․발전하여 오늘날에도 활발하게 전승·통용되고 있다. 차 제조 방법 및 음다 방식 등에서도 우리나라만의 고유성이 있다. ※ 국가무형유산 ‘○○’는 한반도 남부 지방의 차산지에 기반을 두고 있으며, 차 제조 기술이 다양한 방식과 형태로 일반적으로 공유·전승되고 있으…","a":"제다","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/2016101118032200.jpg"},{"q":"○○○○는 고된 농사일을 해오던 머슴들이 음력 7월 15일 백중날 하루 휴가를 얻어 흥겹게 놀던 것을 말하며 흔히 이 날을 머슴날이라고도 한다. 연산 ○○○○는 논산 두마면 왕대리를 중심으로 연산면 일대에서 전승되어 왔으며 조선 성종(재위 1469∼1494) 때 좌의정을 지낸 김국광의 업적을 기리기 위해 백중날 묘에 참배하고 한바탕 놀았던 것이 후에 광산 김씨들이 연산일대로 옮겨오면서 연산장터에 모여 놀이를 벌였던 것으로 전해진다. 연산 ○○○○는 제를 지내고, 효자효부에 대한 상과 불효자에 대한 벌을 논하고, 그해 농사를 잘 지은 머슴을 뽑아 상을 주는 당시의 풍습…","a":"연산백중놀이","c":"시도무형유산","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643981.jpg"},{"q":"떡살, 다식판을 만드는 문양각 기능으로서 불상조각기법과 다른 우리생활에 필요한 전통 민속 조각기법으로 생활이나 풍습에 관계가 있고, 문화적인 측면이나 미술사적으로 우리 생활에 필요한 매우 중요한 전통조각기술이다. 김규석은 이주철선생에게 목조각, 문양각을 배우고 이연채선생에게 떡살, 다식판 기술을 배워 기술 구사능력과 학술적 뒷받침이 탁월하여 체계적으로 전승하고 있다.","a":"목조각장","c":"시도무형유산","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2020082518030300.jpg"},{"q":"잡가는 상층문화권의 정통가요인 가곡, 시조에 비해서 정제되지 못한 노래, 곧 잡스럽거나 속된 하층문화권의 노래, 속가 또는 잡가라는 의미가 들어 있다. 이것은 경기체가와 더불어 고려시대 가요의 한 몫을 차지하던 장르의 잡가와는 다른 용어인 바 조선 후기 광대나 사당패 등 전문적인 소리꾼들에 의하여 집중적으로 창출된 잡가(속가)를 지칭하는 것이다. 원래 잡가는 조선 말기에 형성되고 번창하다가 1830년을 전후하여 유행가 등 서양풍의 노래에 밀려난 노래의 문학이라고 할 수 있다. 따라서 잡가는 조선조의 마지막을 장식하는 문학장르라는데 문학사적 의미가 있으며, 현재와 과거…","a":"남도잡가","c":"시도무형유산","r":"전남광주통합특별시","s":"진도군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018101615075100.jpg"},{"q":"진달래 꽃잎을 섞어 담는 향기나는 술로 진달래꽃을 두견화라고도 하므로 두견주라고 부른다. 두견주는 고려의 개국공신인 복지겸(卜智謙)에 얽힌 전설이 있다. 그가 병이 들어 온갖 좋다는 약을 다 써도 병이 낫지 않자, 그의 어린 딸이 아미산에 올라 100일 기도를 드렸다. 신선이 나타나 이르기를 아미산에 활짝 핀 진달래꽃으로 술을 빚되 반드시 안샘(지금 면천초등학교 뒤에 있는 우물)의 물로 빚어 100일 후에 마시고 뜰에 2그루의 은행나무를 심어 정성을 드려야만 효과가 있다고 하였다. 딸이 그대로 하였더니 아버지의 병이 나았다고 한다. 술의 색은 연한 황갈색이고 단맛이…","a":"면천두견주","c":"국가무형유산","r":"충청남도","s":"당진시","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623757.jpg"},{"q":"○○ 안성 ○○○○는 음력 정월 대보름날, 모내기 전 혹은 4월 초파일, 7월 보름에 숯가루·사금파리·소금·마른 쑥 등을 넣은 낙화봉을 긴 줄에 매달아 놓고 거기에 불을 붙여 그것이 타오를 때 나오는 불꽃 모양과 터지는 폭음 소리를 함께 즐기는 우리나라 전통 민속놀이를 말한다. 이를 ‘줄불 놀이’, ‘줄불이’ 등이라고도 한다. 1. 불놀이 종류와 ○○○○ 토화(吐火), 폭죽, 연등놀이, 화산대(火山臺), 줄불-○○○○, 불단-○○○○, 달걀 불놀이, 횃불 놀이, 딱총 놀이 등이 있다. 2. ○○○○의 지역적 분포 함경남도 북청 지방의 ‘연등’, 평안북도 정주 지방의…","a":"무주 안성낙화놀이","c":"시도무형유산","r":"전북특별자치도","s":"무주군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2020030618395500.JPG"},{"q":"■ ○○○○의 유래 0 고려 의종때 부산동래로 귀양갔던 정서가 임금을 그리워하여 지은 정과정곡이 조선시대에는 가곡(歌曲)으로 정착했고 이 가곡에서 시조가 파생됨 0 가곡과 시조는 시조시(時調詩)를 노랬말로 사용함. 시조는 가곡을 음정과 장단을 단순화 하여 누구나 쉽게 부를 수 있도록 되어 있어서 대금과 장구 반주만으로 연주가 충분하며 나아가서는 무릎장단만으로도 연주를 하므로 단순하고 담백하며 전문 가객이 아닌 선비와 사대부들이 즐겼던 노래임. 0 가곡을 축소하고 단순화하여 여유와 멋을 한껏 표현할 수 있도록 한 노래가 시조어임 이를 나타내는데 모든 조건을 완전히 갖춘…","a":"영제시조","c":"시도무형유산","r":"경상남도","s":"의령군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644655.jpg"},{"q":"○○○○은 강원특별자치도 태백산맥 동쪽에 전승되어 오는 대표적인 영동농악의 하나로 농경생활을 흉내내어 재현하는 농사풀이가 있기 때문에 농사풀이농악이라고도 한다. 유래에 관한 정확한 기록은 없으나 농경생활을 시작하면서부터 발생한 것으로 추측된다. ○○○○은 농기, 쇄납(날라리), 꽹과리, 징, 북, 장구, 소고, 법고(불교의식 때 쓰는 작은북) 및 무동(사내아이)으로 편성된다. 연주자들은 흰 바지저고리에 홍·청·황의 삼색띠를 두르고 무동들은 여러 가지 색깔이 섞인 옷을 입는다. ○○○○에는 정월 대보름을 전후해서 3∼4일간 농악대가 집집마다 다니면서 농악과 고사를 나는…","a":"강릉농악","c":"국가무형유산","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1779866.jpg"},{"q":"○○○○는 노래와 춤이 하나로 어우러진 부녀자들의 집단놀이로 주로 전라남도 해안지방에서 추석을 전후하여 달밤에 행해졌다. 임진왜란 때 이순신 장군이 왜군에게 우리의 병사가 많다는 것을 보이기 위한 의병술로 마을 부녀자들을 모아 남자 차림을 하게 하고 옥매산을 돌게 한데서 비롯되었다는 설이 있으나, 원시시대부터 1년중 가장 달이 밝은 밤에 축제를 벌여 노래하고 춤추던 풍습에서 비롯된 민속놀이라고 보는 것이 타당하다. 동쪽 하늘에 둥근 달이 떠오르기 시작하면 여인들은 손에 손을 잡고 오른쪽으로 돌며 둥근 원을 그려나간다. 목청 좋고 소리 잘하는 사람이 맨 앞에 서서 메기…","a":"강강술래","c":"국가무형유산","r":"전남광주통합특별시","s":"진도군","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623803.jpg"},{"q":"○○○은 대량 인출이 필요한 서적을 만들기 위하여 책판의 글자와 세밀한 그림을 새김과 동시에 책판의 관리, 보수와 장판(藏板)을 전담하는 장인이다. 고인쇄문화의 중심지로 자리매김한 지역적인 특성을 고려할 때 충청북도의 목판인쇄문화를 이어갈 무형유산 종목으로 지정하여 보존하고자 한다. ○ 더불어 책판 전통 새김 기법 등의 끊임없는 연구와 체계적이고 다양한 사고를 통해 계승 발전에 노력하고 있는 박영덕을 ○○○ 기능 보유자로 인정하여 명맥을 유지하고자 한다.","a":"보은 각자장","c":"시도무형유산","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2020032315264100.JPG"},{"q":"○○○는 민속주의 하나로 증류식 소주다. ○○○는 1880년경부터 충남 서산 유씨인 유성근柳盛根이 그의 부친을 따라 전북 남원 산동으로 이사하여 최초로 옥로 소주를 빚게 되었으며 그 후 1947년 초에 경남 하동의 양조장에서 유양기가 알코올 농도 30％ 소주를 생산하면서 ‘○○○’라는 상표를 붙였다. 술을 증류할 때 증기가 액화되어 마치 옥구슬 같은 이슬방울이 떨어지는 것을 보고 ○○○라는 이름을 붙였다고 한다. ○○○는 좋은 질의 지하수와 우리나라 재래종인 백미白米와 소맥小麥에다 특이하게 율무를 사용한다. 일반 누룩과는 다르게 밀과 율무를 누룩으로 사용한다. 분쇄한…","a":"옥로주","c":"시도무형유산","r":"경기도","s":"안산시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643630.jpg"},{"q":"「○○○가」는 황해도지역 대표적 민요로서 무녀들이 굿을 할 때 불렀던 토속무가이며,「○○○」는 홍경래의 난 이후 관서지방민에 대한 차별정치로 인한 통탄과 울분을 지역민들의 한의 소리로 승화된 향토민요이다. 특히 황해도에서는 “부처님이 노여워하시니 ○○○을 모르면 절간에 가지마라”, “문 앞에 선 낭군님 ○○○를 알고 있나 물어라” 등의 말이 세간에 퍼져 있을 정도로 「○○○가」및「○○○」는 대표적인 향토민요로서 황해도지방의 언어, 생활, 풍속 등 전통적 지역정서가 배어 있다.","a":"서도소리‘산염불·난봉가’","c":"이북5도 무형유산","r":"황해도","s":"전역","i":"http://www.khs.go.kr/unisearch/images/nondesignated_cult_prop/2724481.jpg"},{"q":"탱화는 불교적인 소재와 교리를 경건하고 아름답게 표현한 그림으로서, 세계적으로 명성이 높은 고려시대에 이르러 최고의 기술적 완성을 이루었으며, 조선시대에는 대중적 기호에 맞는 민중미술로서 크게 성행하였다. 전라도 지역은 예로부터 의겸(義謙)스님을 비롯하여 천여(天如)·익겸(益謙) 등 뛰어난 화승(畵僧)들을 많이 배출한 지역이다. 기능보유자 유삼영은 만응(萬應)스님으로부터 탱화수업을 받은 이후 30여년간 전라도 및 제주도에서 많은 작품을 제작하고 있다. 그의 탱화는 각 부문에서 주제별 도상(圖上)에 필요한 초본(草本)으로 탱화를 조성하여 전통문화의 맥을 충실히 잇고 있…","a":"탱화장","c":"시도무형유산","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644146.jpg"},{"q":"○○○는 소리꾼 한 명이 고수(북치는 사람)의 장단에 맞추어 창(소리), 말(아니리), 몸짓(너름새)을 섞어가며 긴 이야기를 엮어가는 것을 말한다. ○○○는 순조(재위 1800∼1834) 무렵부터 ○○○ 8명창이라 하여 권삼득, 송흥록, 모흥갑, 염계달, 고수관, 신만엽 등이 유명하였는데 이들에 의해 장단과 곡조가 오늘날과 같이 발전하였고, 동편제(전라도 동북지역)·서편제(전라도 서남지역)·중고제(경기도, 충청도) 등 지역에 따라 나뉘어 졌다. ○○○가 발생할 당시에는 한 마당의 길이가 그리 길지 않아서 ○○○ 열두마당이라 하여 그 수가 많았으나 현재는 ○○○ 다섯마…","a":"판소리(수궁가)","c":"시도무형유산","r":"경상남도","s":"사천시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644450.jpg"},{"q":"○○○ 김범식은 소목일을 하던 부친의 영향을 받아 어린 시절부터 목공일을 할 기회가 많았다. 1964년 22세 때 한국전통목조건축 제작에 입문, ○○○ 김윤원(작고, 한식목공 제859호)에게 본격적으로 목공기술을 배우기 시작했다. 김윤원은 사찰 목수의 명인으로 알려진 김덕희의 아들로, 김범식의 전승계보는 김덕희-김윤원-김범식으로 이어진다고 할 수 있다. 김범식은 도편수 김덕희가 맡은 김천 직지사에서 처음으로 공사에 참여한 후 여러 공사에서 수련과정을 거치면서 건축 연장 사용기술, 설계도면 작성법, 치목법 등을 전수받았다. 1972년 정식 도편수로 맡은 이래 50년이란…","a":"대목장","c":"시도무형유산","r":"경상북도","s":"경산시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2016111608413500.jpg"},{"q":"궁장이란 활을 만드는 기술 또는 사람을 말한다. 활은 삼국시대 훨씬 이전부터 사용되었으며 옛날 중국에서는 우리 민족이 ‘활을 잘 만들고 잘 쏘는 동쪽의 민족’이라 해서 ‘동이(東夷)’라고 부를 만큼 활제작에 있어서 탁월한 기술을 가졌다고 전해진다. 임진왜란(1592) 이후 조총이 수입되기 전까지 전쟁의 무기로 사용되었고 현재는 운동용으로 국궁인 각궁(角弓)이 보편화 되었다. 오늘날 서양에서 들어온 양궁(洋弓)과 구별하기 위해 국궁(國弓)이라고 부르고 있다. 제작과정으로는 우선 대나무 조각·뽕나무 조각·물소뿔 등을 다듬는다. 대나무와 뽕나무는 불에 쬐어 구부린 다음 연…","a":"예천궁장","c":"시도무형유산","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644300.jpg"},{"q":"세도 ○○○○은 부여군 소재지에서 동남쪽 15㎞지점에 있는 세도면 동사리 마을에서 오래전부터 내려오는 마을공동체 놀이이다. 이곳 동사리 마을은 남향에 넓은 앞뜰에 펼쳐진 논농사위주의 노동집약 농업형태로 이어져온 전형적인 농촌마을이다. 이 동네에서는 논농사철을 본격적으로 맞게되면 거동적으로 두레조직을 만들어 농사를 짓는 전통이 있어 두레농사 짓는 것을 \"두레먹는다\"라고 한다. 협업과 공동오락이 잘 이루어진 세도 ○○○○은 질굿가락, 칠채가락, 논풍장가락, 쩍쩍이가락, 두렁질굿가락, 자진마치가락, 마당밟이가락, 두마치가락, 매조지가락으로 구성되어 있으며 '가락'이나 '판…","a":"세도두레풍장","c":"시도무형유산","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644015.jpg"},{"q":"농요는 논이나 밭에서 일을 하면서 피로를 잊고 능률을 올리기 위해 부르는 노래로 들노래 또는 농사짓기 소리라고도 한다. 토속민요의 하나인 농요는 개인 또는 집단적으로 부르며, 지방에 따라서 노래가 달라질 수도 있다. ‘마들’이란 지명의 유래는 상계동에 역참기지가 있어 말들을 들판에 풀어 놓아 길렀기 때문이라는 설과 이 일대가 삼밭이어서 삼밭의 순 우리말인 ‘마뜰’에서 비롯되었다는 설이 있다. 내용으로는 모심는소리와 논매기소리가 있다. 논매기소리는 호미로 처음 맬 때의 두루차소리, 두벌 맬 때의 미나리, 다 매갈 무렵 저녁에 신나게 부르는 꺽음조 등으로 구성되어 있다.…","a":"마들농요","c":"시도무형유산","r":"서울특별시","s":"노원구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018102317393300.jpg"},{"q":"농요는 논이나 밭에서 일을 하면서 피로를 잊고 능률을 올리기 위해 부르는 노래로, 들노래 또는 농사짓기 소리라고도 한다. 토속민요의 하나로 개인 또는 집단적으로 부르며 지방에 따라서 노래가 달라질 수도 있다. ○○○○○는 부녀자들이 농사일을 하면서 부른 민요이다. 내용은 밭매기노래, 보리타작노래, 방아타령, 둥덩이타령, 길꼬냉이, 뒷풀이 등으로 구성되어 있다. 밭매기는 밭을 맬 때 부르는 노래이고, 보리타작은 도리깨로 보리타작을 하면서, 방아타령은 방아를 찧으면서, 둥덩이타령은 일을 하다가 쉴 때 부르는 노래이다. 길꼬냉이는 일을 마치고 집으로 돌아오면서 부르는 노래…","a":"우수영부녀농요","c":"시도무형유산","r":"전남광주통합특별시","s":"해남군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644207.jpg"},{"q":"○○은 두껍고 질긴 나뭇잎을 입술에 대고 입김을 불어 연주하는 악기이며 동시에 이것으로 연주하는 음악을 가리킨다. 일명 초금(草琴)이라 하였고 풀피리라 이르기도 한다. 조선 성종 24년(1493)에 성현 등이 편찬한 궁중음악서인 『악학궤범』 권7 향부악기도설(鄕部樂器圖說)에 ○○에 대한 설명과 그림이 그려져 있다. 영조 20년(1744)의 궁중 진연 의식을 기록한 『진연의궤』에 관현맹인(管絃盲人) ○○ 악사 강상문(姜尙文)의 기록으로 보아 조선조에 궁중에서 연주되었음을 알 수 있다. 또한, 일제강점기에 활동한 남도 판소리 명창인 강춘섭(姜春燮)은 유성기 음반에 판소리…","a":"초적","c":"시도무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018102317411400.jpg"},{"q":"한국의 전통적인 제의식에는 상주권공재, 생전예수재, 시왕각배제, ○○○, 수륙재의 다섯 종류가 있다. 상주권공재는 죽은 사람의 영혼을 천도하는 가장 규모가 작은 재, 생전예수재는 살아 있는 사람이 죽은 후에 영혼을 천도해 주기를 바라며 미리 행하는 재이며, 시왕각배재는 명부의 十王에게 천도를 위해 재를 올리는 의식으로 중간 규모의 재이고, ○○○는 규모가 가장 큰 재로 국가나 기관 등의 주재로 국가나 기관 등에 중요한 인물들의 천도를 기리기 위해 치루어지는 경우가 많은 재이며, 수륙재는 본래 물과 육지에 떠도는 孤魂을 위해 베푸는 재로 불교의 종교적 의미가 가장 많이…","a":"불모산영산재","c":"시도무형유산","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018103111374900.jpg"},{"q":"예로부터 우리나라 사람들은 그 해의 나쁜 운을 풀기 위해 굿판을 벌였는데 그곳에서 무당이 즉흥적으로 나쁜 기운을 푸는 춤을 춘 것을 ○○○○이라 하며, 도○○○○·허튼춤·입춤·수건춤·즉흥무(卽興舞)라고도 한다. 전해내려오는 말에 의하면 신라시대의 도솔가는 도살풀이·살풀이라고 해석되며, 시나위(남도무악)는 향가(鄕歌) 중 사승가(詞勝歌)의 맥과 통한다고 한다. 춤꾼은 고운 쪽머리에 비녀를 꽂고 백색의 치마저고리를 입으며, 멋스러움과 감정확대를 위해 하얀 수건을 든다. 살풀이장단에 시나위를 연주하되 피리, 대금, 장구, 아쟁, 북 등의 반주로서 춤을 춘다. ○○○○은 오…","a":"살풀이춤","c":"시도무형유산","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643481.jpg"},{"q":"○○○○○는 남부형 민속가면극으로 19세기 후반부터 연희되어 왔을 것으로 추정되며, 1937년 무렵 일제강점기의 민족문화 말살정책에 의해 중단된 이후, 1980년대 중반 김해문화원에서 들여와 재연을 시작하여 당시 김해군 이북면(현 한림면)의 첫 공연이 연희되었으며, 보존회를 통하여 꾸준히 전승 및 연희되고 있다. ○○○○○는 모두 여섯 과장으로 첫째과장 중과장, 둘째과장 노름꾼과장, 셋째과장 양반과장, 넷째과장 영노과장, 다섯째과장 할미영감과장, 여섯째과장 사자무과장으로 구성되어 있다. 내용은 대개 파계승의 풍자, 양반에 대한 조롱, 일부(一夫)대 처첩간의 삼각관계,…","a":"김해오광대","c":"시도무형유산","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2394603.jpg"},{"q":"\"낙죽(烙竹)이란 불에 달군 인두로 대나무 표면을 지저 글씨나 그림, 문양 등을 그리는 죽세공예의 한 분야이다. 여타의 죽세공예와 함께 예로부터 담양지역에서 성행하였으며 최근까지 전승되어 왔다. 국가무형유산 기능 보유자 ○○○ 이동연(李同連, 1969. 11. 29.지정)에 이어 국양문(鞠良文, 1987. 1. 5. 지정)이 지정되었다. 국양문이 세상을 떠난 뒤 김기찬(2000.7.22 인정, 전남 순천시)이 보유자로 인정되었다. 분업적 형태로 발달하여 온 죽세공예 중에서 낙죽은 장식성을 가미하여 상품의 질을 높이는 공정인 바, 여타의 죽세공예와 유기적 연관성 및 ‘…","a":"낙죽장","c":"시도무형유산","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644238.jpg"},{"q":"○○는 전통사회에서 선비들이 일정한 음률로 한문이나 소설 등을 읽는 행위를 지칭한다. ○○는 내용이 한문으로 된 것과 소설이 있는 바, 전통사회에서는 이것이 일종의 양반 사대부의 교양이 되었던 것이다. ○○는 예술성과 역사성이 아울러 갖춰져 있다. 대체로 ○○는 서울 지역의 음악어법으로 부른다. 그렇기 때문에 ○○는 조선시대의 산물이라는 역사성과 서울이라는 지역성을 그 특징으로 한다. 2009년 3월 5일 유의호(유창)가 보유자로 인정받아 활동하고 있다.","a":"송서","c":"시도무형유산","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018102409264900.jpg"},{"q":"1944년에 태어난 임순옥은 이모이자 스승인 서정순으로부터 바느질을 배웠다. 임순옥은 조선왕조 궁중의상 복식 등 전통복식 제작에 종사해 왔고, 공방을 통해 많은 제자를 양성하고 있다. 대한민국 한복, 침선 문화상품 공모대전, 전라북도 기능경기대회, 대한민국 미대회 등의 다수 수상 경력이 있다.","a":"침선장(전통복식, 임순옥)","c":"시도무형유산","r":"전북특별자치도","s":"군산시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644138.jpg"},{"q":"○○○은 청자를 만드는 사람 또는 기술을 말한다. 청자 제작 과정은 매우 복잡하고 정성과 정밀을 요하는 작업으로 대부분 유사한 과정을 거치는데 제토[製土, 水飛]와 성형(成形), 정형(整形), 조각(彫刻), 장식, 초벌구이(初燔), 시유(施釉), 재벌구이(再燔) 등 완성품이 되기까지는 60∼70여일의 기간에 24∼25단계의 공정을 거친다. 그리고 청자의 신비스러운 비색을 재현하기 위해서는 불과 태토(胎土), 유약의 3요소가 조화를 이루어야 되며, 가마 내에서 불의 작용과 기상 조건에 따라 변화 무쌍한 현상을 일으키기 때문에 제작에 매우 많은 어려움이 있다. 이용희는…","a":"청자장","c":"시도무형유산","r":"전남광주통합특별시","s":"강진군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018101118291200.jpg"},{"q":"○○○○○는 삼국시대부터 조선시대를 거쳐 전해 내려오는 국가의식의 하나로 양산시 ○○○사제례를 바탕으로 형성된 민속놀이이다. 처음에는 그저 제물을 차려 천신과 지신, 용신에게 빌고 노래와 춤으로써 한바탕 잔치를 벌였던 것이 점차 변형되어 오늘날에 와서는 부정굿, 칙사영접굿, 용신제, 용소풀이, 사신풀이 등으로 구분하면서 제사와 놀이로 구성되었다. ○○○○○는 마을과 ○○○사 주위를 돌면서 칙사 맞을 준비인 제당과 마을을 청소하는 것으로 시작한다. 부정굿으로 부정을 막는 금줄을 치고, 황토를 뿌리고 칙사 영접길에 오르는데 선창자가 길을 밟는 지신풀이를 하고, 나머지 일…","a":"가야진룡신제","c":"시도무형유산","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644489.jpg"},{"q":"■ ○○○○○ 우리의 민속문화 중에서 경기도와 충청도에만 분포하는 놀이가 있으니, ‘○○○○’가 바로 그것이다. 이 ○○○○는 추석에 수숫대를 벗겨 거북의 모양을 만들고 그 속에 사람이 들어가, 마을을 돌아다니면서 길놀이, 우물굿, 마을놀이, 문굿, 터주굿, 조왕굿, 대청굿, 마당놀이 등을 순서대로 펼치는 민속놀이다. 다른 민속놀이에 비하여 추석 때에 주로 이루어지는 점, 거북을 만드는 재료가 수숫대인 점, 중부 내륙지방에만 이 놀이가 분포하고 있는 점 등이 특징적이다. 또 마을을 돌며 놀이판을 펼치면서 마을의 전체와 각 가정의 재액災厄을 물리치고 복을 기원해주는 제…","a":"이천거북놀이","c":"시도무형유산","r":"경기도","s":"이천시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2187753.jpg"},{"q":"‘○○’는 오랜 역사와 전통 속에서 다양한 형태로 지속하여 왔으며, 우리 민족의 정체성과 가치를 대표해 온 전통생활관습이자 전통지식이다. ○○는 음력 5월 5일로 양기(陽氣)가 가장 성한 날로 예로부터 중오(重午), 천중절(天中節), 수릿날이라 불렀으며, 여름의 대표 명절이다. ○○가 우리 문헌에 처음 등장하는 것은『삼국유사』이며, ○○에도 국가의례로 왕실제사를 지낸 내용을 확인할 수 있다. 고려시대와 조선시대 기록을 통해 ○○의 핵심 요소인 ○○제, 그네뛰기, ○○ 부채 관련 풍속도 확인이 가능하다. 다른 명절에 비해 ○○는 단일 주제로 가장 많이 연구되었으며, 설…","a":"단오","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/2023121814424200.jpg"},{"q":"‘○○○○’은 오랜 역사와 전통 속에서 다양한 형태로 지속하여 왔으며, 우리 민족의 정체성과 가치를 대표해 온 전통생활관습이자 전통지식이다. ‘○○○○’은 바지·저고리 또는 치마·저고리로 이루어진 2부식 구조, 옷고름을 갖추고 있는 한복(韓服)을 지어, 예절·격식·형식이 필요한 의례·관습·놀이 등에 맞춰, 치마-저고리, 바지-저고리 착용 순서에 따라 입고 향유하는 문화를 뜻한다. 가족 공동체를 중심으로 전승되고 있는 ‘○○○○’은 설·추석 명절뿐만 아니라 돌잔치·결혼식·상장례·제례 등 일생의례를 통해서도 여전히 행해지고 있는데, 점차 그 빈도와 범위가 줄어들고 있으나…","a":"한복생활","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/2022072513445100.jpg"},{"q":"이길주는 1950년에 전주에서 태어나, 최선에게 입문하여 한국무용을 익혔다. ○○○○○은 이추월-최선-이길주로 이어지는 기방계 전통춤으로서 즉흥형식의 산조연주에 맞춰 최고의 춤사위를 발휘하는 한국 춤의 대표적 특성인 한과 신명을 한층 더 자유롭게 승화시킨 춤이다. 이길주는 대한민국 무용제, 이탈리아 시실리아댄스 페스티발 등 다수 대회에서 입상하였다.","a":"호남산조춤","c":"시도무형유산","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644171.jpg"},{"q":"○○○이란 장구·북·단소·가야금·거문고 등 전통음악에 쓰이는 악기를 만드는 기술 또는 그 기능을 가진 사람을 말한다. 호남농악의 발상지인 전북지역은 수준높은 풍물악기의 제작 및 보급이 원활한 지역적 특성을 가지고 있다. 장구는 대표적인 리듬악기로 고려 때 중국 송나라로부터 수입되어 오늘날까지 여러 분야에 걸쳐 널리 사용되고 있다. 장고 또는 세요고라고도 부르며, 말가죽과 소가죽이 재료로 쓰인다. 북은 나무로 짠 통에 가죽을 씌우고 채로 두드려 연주하는 악기로 흔히 소나무 여러 조각을 모아 북통을 짜고 양면에 소가죽을 맨다. 궁중음악에 쓰이는 것은 대부분 못으로 박아…","a":"악기장","c":"시도무형유산","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644111.jpg"},{"q":"가야금을 타면서 노래를 부르는 것을 ○○○○○이라 한다. ○○○○○은 단가나 판소리 중 한 대목을 따다가 가야금반주를 얹어 부른다. ○○○○○은 원래 가야금산조의 명인들이 불렀지만, 오늘날에는 산조와 병창의 연주자가 분리되는 추세이다. 원곡이 따로 있는 노래를 병창으로 부를 때에는 가야금 특유의 선율로 인해 본래의 곡과 다른 맛이 나고 독특한 개성을 표현하게 된다. 판소리 흥보가 중 “제비노정기”, 춘향가 중 “사랑가”, 수궁가 중 “고고천변”, 심청가 중 “심봉사 황성가는 대목”은 ○○○○○의 유명한 대목이다.","a":"가야금병창","c":"시도무형유산","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2022093011433100.JPG"},{"q":"등메는 침상이나 평상 위에 깔아 사용하는 자리를 말하며 보료로 이용하기도 한다. 그 재료는 용수초(龍鬚草)라는 식물로 왕골과는 구분되며,우리나라의 논 또는 개울이나 습지에서 널리 자생한다. 가늘고 길며 단면이 둥근 줄기 안에 스펀지처럼 탄력 있는 심을 가진 풀이며,;골풀'로도 불린다. 현재 이 풀을 이용해 다양한 가물을 만드는 장인으로는 초고장(草藁匠)과 ○○○이 있다. 초고장이나 완초장은 자리,돗자리,방석, 외에 동구리,합 등의 생활기물 및 장신구까지 제작하는 장인이 ○○○이다.등메라는 용어는 골풀로 앞바탕을 짜고 뒷면에는 탄력을 위해 부들을 덧댄데서 비롯한 것으로…","a":"등메장","c":"시도무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018102317464000.jpg"},{"q":"○○은 발에 탈을 쓰고 노는 놀이이다. 유래에 대한 정확한 기록은 남아 있지 않지만 경기도 안성지방의 남사당패가 행하던 꼭두각시놀음이 변형되어 주로 중부지방에서 연희되었던 것으로 추측된다. ○○은 처음에는 허수아비 모양으로 만든 인형의 머리부분을 탈꾼의 발바닥에 씌우고 팔은 노끈으로 연결하여 당기거나 놓으면서 조종했다고 한다. 그 후 광무대 시절에 박춘재는 직접 손에 한삼을 끼고 공연하였으며, 남형우는 양팔 끝에 노끈을 연결시켜 위로 올린 것을 대나무에 연결하고 그 대나무를 양손으로 조종하면서 ○○놀이를 하였다. 초대 ○○ 예능보유자인 이동안 씨는 두 가지 방법으로…","a":"발탈","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623301.jpg"},{"q":"칠(漆)은 옻나무과의 수액으로, 각종 공예품에 옻을 입히는 재료이다. 옻칠의 여러 종류 중 정제칠은 다양한 채색안료의 접착제로 이용되는 2차 가공 공정을 말한다. 칠은 옻나무에서 채취한 옻칠과 황칠나무에서 채취되는 황칠이 있다. 제조과정과 배합재료 및 제작과정에 따라 1차 공정에서 날칠, 즉 생칠이 생산되고, 2차 공정에서 정체칠이 완성된다. 그러므로 옻나무에 트집을 내어 받아낸 생칠과 옻나무를 벌채하여 불에 구운 다음 수분을 제거하여 얻어낸 익은 옻칠인 정제옻으로 나뉜다. 칠정제는 우리나라 나전 및 칠공예의 근간을 이루는 기술로서, 원주 지역에서는 전통적 방식으로…","a":"칠정제장","c":"시도무형유산","r":"강원특별자치도","s":"원주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018101515031200.jpg"},{"q":"바디는 베를 짜는 베틀의 한 부분으로 이를 만드는 기술과 그 기술을 가진 사람을 ○○○이라 한다. 옷은 엣부터 사람들의 의·식·주 생활에 있어서 중요한 부분을 차지해 왔으며, 신석기시대의 유적지에서 실을 뽑은 가락에 끼우는 방추차가 발견된 것으로 보아 이미 신석기시대에 베를 짜기 시작했음을 알 수 있다. 바디는 대나무의 껍질로 만드는데, 3~4년이 지난 대나무라야 껍질이 단단하고 두터워 재료로서 적합하다. 제작과정을 보면 바디살 만드는 과정, 기둥살(일명 날대) 만드는 과정, 마구리를 끼우는 과정, 그리고 갓 붙이는 과정 등으로 구분된다. 바디의 종류는 모시베, 명주…","a":"바디장","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1624413.jpg"},{"q":"○○○는 통일신라시대인 9세기에 이미 확인되며, 고려와 조선시대를 거치면서 계속되어왔다. 신라와 고려의 ○○○는 불교적 행사였지만, 조선시대에는 민속행사로 행해졌고 해방이후 전통적인 시련, 탑돌이의 행렬 문화가 확대되어 연등행렬로 발전하였다. ○○○는 관불의식, 연등행렬, 회향의 형식으로 진행되며 연등행렬 때 동원되는 등(燈)이 다양하고 다채롭다. 불교가 우리나라에 들어온 이래 ○○○는 통일신라와 고려, 조선시대를 거치면서 궁중과 서민 모두를 아우르는 중요한 문화행사였다. 역사적으로는 고려의 ○○○가 사회적 기능이 가장 컸었고, 유교가 성했던 조선시대에서도 ○○○는…","a":"연등회","c":"국가무형유산","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623416.jpg"},{"q":"단청은 광물성 안료인 진채(眞彩)로 건조물이나 공예품 등에 채색을 올리는 것을 말한다. 단청을 하면 목재의 보존에 유리하고 또 목재부분의 조악한 부분을 가릴 수 있으며 건물을 장엄하게 하는 데 도움이 된다. 단청은 불교미술의 한 분야로 불교의 교리와 이념을 표현하는 작업으로 오랜 우리 역사 속에 면면히 이어져 내려오고 있다. 예전에는 단청에 종사하는 사람을 화사(畵師)·화원(畵員)·화공(畵工)·도채장(塗彩匠) 등으로 불렀다. 만일 그가 승려인 경우에는 금어(金魚) 또는 화승(畵僧)이라 하였다. ○○○ 이정오는 어려서부터 우리나라 단청계 최대 계파의 수장인 고 일섭스님…","a":"단청장","c":"시도무형유산","r":"대전광역시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643581.jpg"},{"q":"○○○이란 불에 달군 인두를 대나무에 지져가면서 장식적인 그림이나 글씨를 새기는 기능 또는 그 기술을 가진 사람을 말한다. 낙죽은 온도를 맞추어 그려야 하고 인두가 식기 전에 한 무늬나 글씨를 마무리지어야 하기 때문에 작업 경험과 속력을 필요로 하는데, 주로 화살대·침통·칼자루·병풍·담뱃대·부채·대나무필통 등에 쓰인다. 낙죽은 접는 부채의 맨 처음과 마지막에 쓰이는 두꺼운 대나무(합죽선)살에 가장 많이 쓰인다. 합죽선에는 나비무늬를 많이 사용하지만 간혹 박쥐무늬도 보인다. ○○○○○ 이신입은 공방을 운영하면서, 전통 낙죽기법의 보존 전승 및 전수를 위해 심혈을 기울이…","a":"전주 낙죽장","c":"시도무형유산","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2022093013102700.jpg"},{"q":"농악은 농부들이 두레를 짜서 일할 때 치는 음악으로 꽹과리·징·장구·북과 같은 타악기를 치며 벌이는 음악을 두루 가리키는 말이다. 전라남도의 농악은 구성방식·복장·음악성 등을 기준으로 볼 때 크게 좌도굿, 우도굿, 도서해안굿으로 분류할 수 있다. 이중 도서해안굿은 남해와 서남해 일대인 고흥군 금산면과 완도, 진도 일대에서 행하여지는 농악으로 길굿이 육지의 것과 다르고 당제를 중심으로 신과 친근성을 지니는 등 좌도·우도 어느 지역권에도 속하지 않는 독자성을 지니고 있다. 고흥 ○○○○은 도서해안굿의 일종으로, 임진왜란(1592) 당시 군대의 사기를 돋우기 위해 농악을…","a":"고흥월포농악","c":"시도무형유산","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2019082619551400.JPG"},{"q":"○○○이란 기와를 전문으로 만드는 사람을 말한다. 기와는 건축물의 지붕에 빗물이나 습기가 새어들지 못하게 덮어 씌워 침수를 막고 흘러내리게 하여 지붕 밑에 있는 목재의 부식을 방지함과 동시에 건물의 경관과 치장을 돋보이게 하는 것이다. 한때 장식적인 효과와 더불어 권위와 부의 상징이기도 하였다. 기와는 암키와와 수키와가 있으며, 부속장식 기와로는 암막새와 수막새, 귀면기와, 치미(치尾), 용두(龍頭), 망와(望瓦) 등이 다채롭게 개발되었다. 기와를 만드는 공정은 찰진 진흙으로 된 점토를 물과 반죽하여 나무로 만든 모골(模骨)이란 틀에 넣는다. 모골의 외부에 마포나 무…","a":"제와장","c":"국가무형유산","r":"전남광주통합특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623926.jpg"},{"q":"○○○○○은 조선시대 역대 왕과 왕비의 신위를 모신 사당(종묘)에서 제사(종묘제례)를 지낼 때 무용과 노래와 악기를 사용하여 연주하는 음악을 가리키며, ‘종묘악’이라고도 한다. 종묘제례의식의 각 절차마다 보태평과 정대업이라는 음악을 중심으로 조상의 공덕을 찬양하는 내용의 종묘악장이라는 노래를 부른다. ○○○○○이 연주되는 동안, 문무인 보태평지무(선왕들의 문덕을 칭송)와 무무인 정대업지무(선왕들의 무공을 찬양)가 곁들여진다. ○○○○○은 본래 세종 29년(1447) 궁중회례연에 사용하기 위해 창작하였으며 세조 10년(1464) 제사에 적합하게 고친 후 지금까지 전승되…","a":"종묘제례악","c":"국가무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623117.jpg"},{"q":"○○는 고려 중엽에 발생한 것으로 알려져 있으며, 조선시대에 유행한 시가(詩歌) 양식이다.‘시절가’,‘시절단가’,‘단가’라고도 한다. 거문고나 가야금, 대금, 단소, 해금 등 관현악 반주에 맞추어 ○○시(時調詩)를 노래하는 가곡의 영향을 받아 ○○에 곡조가 생겨나면서 ○○창은 지역적 특징을 지니게 되었다. 서울, 경기 지역의 경제(京制)와 향제(鄕制)인 전라도의 완제(完制)· 경상도의 영제(嶺制)·충청도의 내포제(內浦制) 등으로 나뉘게 된 것이다. 경제○○는 서울의 ○○창으로서 지방의 향제○○와 선율이나 시김새, 창법 등과는 다른 특색이 있고 예술적 가치와 전통적 특…","a":"시조","c":"시도무형유산","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018102409352900.jpg"},{"q":"불화(佛畵)는 불탑(佛塔), 불상(佛像) 등과 함께 불교의 신앙 대상으로, 제작 형태에 따라 탱화[幀畵], 경화(經畵), 벽화(壁畵) 등으로 분류할 수 있다. 특히 탱화는 복장식(服裝式), 점안식(點眼式) 등의 신앙 의식 절차를 거쳐 불단(佛壇)의 주요 신앙대상물로 봉안된다. 우리나라 전통사찰에 전해오는 탱화는 불화의 주류를 이루고 있으며, 불화 제작을 담당하는 장인을 특별히 금어(金魚), 화승(畵僧), 화사(畵師), 화원(畵員)이라 부르기도 하였다. 단청과 불화는 제작 목적과 표현방법에서 상당한 차이를 보이는데, 단청은 궁궐·사찰·사원 등의 건축물 벽면에 여러 가지…","a":"불화장","c":"국가무형유산","r":"경기도","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1624432.jpg"},{"q":"○○○○○는 꼭두쇠(우두머리)를 비롯해 최소 40명에 이르는 남자들로 구성된 유랑연예인인 남사당패가 농·어촌을 돌며, 주로 서민층을 대상으로 조선 후기부터 1920년대까지 행했던 놀이이다. ○○○○○는 서민사회에서 자연 발생한 민중놀이로, 양반들로부터 박대를 당해 마을에서 공연하는 것도 자유롭지 못했다. 남사당패는 꼭두쇠를 정점으로 공연을 기획하는 화주, 놀이를 관장하는 뜬쇠, 연희자인 가열, 새내기인 삐리, 나이든 저승패와 등짐꾼 등으로 이루어지지만, ○○○○○는 풍물, 버나, 살판, 어름, 덧뵈기, 덜미 등으로 구성된다. 풍물은 일종의 농악놀이로 공연 시작을 알리…","a":"남사당놀이","c":"국가무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623122.jpg"},{"q":"오광대는 남부지역(낙동강 서쪽지역)의 탈춤을 가리키는 말로 초례 밤마리 마을 장터에서 놀던 광대패들에 의해 시작되었다고 한다. ‘오광대’란 다섯 광대 또는 다섯 마당으로 이루어진 놀이라는 뜻에서 비롯된 이름이라고도 하고, 오행설에서 유래된 오(五)에서 온 것이라고도 하는데, 오행설의 의견이 유력하다. ○○○○○는 제1과장 문둥북춤마당, 제2과장 오광대마당, 제3과장 비비마당, 제4과장 승무마당, 제5과장 제밀주마당 등 5개 과장으로 구성되어 있다. 등장인물은 문둥이, 말뚝이, 원양반, 종가도령, 비비, 중, 각시, 영감, 제밀주 마당쇠 등 19명이 등장한다. 양반과…","a":"고성오광대","c":"국가무형유산","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1624081.jpg"},{"q":"○○은 쇠붙이를 두드려 모양을 내어 기구를 만드는 장인으로 대장간을 운영한다. ○○은 나이와 관계없이 실력에 따라 오르며 메질꾼과 풀무꾼, 심부름꾼의 우두머리 역할을 하였다. 대장기술 습득에 오랜 숙련기간이 필요하고, 가족 외에 기술전수를 꺼리는 풍토로 인해 ○○은 아무나 될 수 없었다. ○○ 보유자 신인영은 ‘안성대장간’의 4대 ○○ 강석봉으로부터 기술을 사사했다. ‘안성대장간’은 당시 안성시내 십여 개의 대장간 중 깊은 역사, 높은 기술력, 큰 규모로 유명했다고 한다. ‘안성대장간’의 전통을 이어받은 강석봉이 처조카인 신인영에게 1966년부터 기술을 전수했다. 신…","a":"야장","c":"시도무형유산","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018091414004100.jpg"},{"q":"경상북도 ○○ 지역은 조선시대부터 질이 좋은 오색점토가 많이 생산되었다. 이처럼 좋은 재료를 이용하여 예로부터 ○○ 지역의 여러 옹기점에서는 질 좋은 옹기를 다량으로 제작할 수 있었다. ○○군 파천면 송강리, 진보면 부곡리, 안덕면 노재 등에는 많은 ○○○들이 옹기를 생산하였고, 이들이 제작한 옹기는 인근 지역은 물론, 전국적으로 유통되었다. 그러나 1970년대 이후 생활 환경의 변화로 플라스틱, 유리, 스테인리스 용기의 사용이 늘어남에 따라 옹기에 대한 수요가 점차 감소하였다. 또한, 전기가마와 같은 설비를 갖춘 현대화된 옹기 공장에서 옹기를 대량으로 생산하면서 전…","a":"청송 옹기장","c":"시도무형유산","r":"경상북도","s":"청송군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2020022009331800.jpg"},{"q":"○○○○○ 노래란 제주도의 해안마을에서 여럿이 그물로 멸치를 후리면서 부르는 민요를 말하며, 멜후림소리라고도 하는데 멜이란 멸치의 제주도 말이다. ○○○○기는 먼바다에서 그물로 멸치떼를 후린 후 모래가 깔린 해안가로 마을 사람들이 일제히 끌어당기는 작업이므로 단결된 힘을 돋우기 위해 노래를 부르게 되었다. 이 민요는 한 사람의 선소리꾼이 노래를 이끌어가고, 그물을 당기는 사람들은 동작에 맞추어 후렴구를 부르는 선후창형식이다. 악곡구조는 두마디 선소리와 두마디 후렴으로 되어 있는데, 선소리와 후렴의 선율은 서로 다르며, 늦은 굿거리장단이나 중중모리장단으로 부른다. 가락…","a":"멸치후리는노래","c":"시도무형유산","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644698.jpg"},{"q":"○○○은 나무로 짠 가구나 기물 위에 무늬가 아름다운 전복이나 조개껍질을 갈고 문양을 오려서 옻칠로 붙이는 기술이다. 나전칠기의 제작과정은, 나무로 기본 틀인 백골을 짜고 그 표면을 사포로 문지르거나 틈새를 메워 고르게 한 다음 자개를 붙인다. 그 후 연마, 옻칠, 광내기 과정을 거쳐 완성한다. 자개로 무늬를 만드는 방법에는 자개를 실처럼 잘게 자른 '상사'로 기하학적인 문양을 만드는 끊음질 기법과, 자개를 문질러 얇게 만들어 국화, 대나무, 거북이 등 각종 도안 문양을 만드는 줄음질 기법이 있다. 나전 무늬는 고려시대와 조선 전기에는 모란·국화·연꽃 등의 식물무늬가…","a":"전주 나전장","c":"시도무형유산","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2022093011474600.jpg"},{"q":"○○○○○란 전라남도 진도지방의 농부들이 농사일을 할 때 부르는 노래를 가리키는데 크게 논일 노래와 밭일 노래로 이루어진다. 모판에서 모를 찔 때에는 모뜨는 소리를 부르고, 논에 모를 심을 때에는 못소리를 부르며 논에서 김을 맬 때에는 절로소리를 부른다. 김매기가 끝나고 농부들이 마을에 들어올 때에는 길꼬냉이를 부른다. 여흥으로 진도아리랑을 부르기도 한다. 농부들이 들일을 하며 노래를 부르는 것은 예로부터 어느 고장에서나 볼 수 있었으나 전라도 서남지역의 노래는 특히 그 종류가 많고 음악성도 뛰어나다. 또한 진도군의 논매는 소리는 전라남도의 다른 지방에 비해 단순한데…","a":"남도들노래","c":"국가무형유산","r":"전남광주통합특별시","s":"진도군","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623853.jpg"},{"q":"예부터 우리 민족이 더불어 살기 위한 다양한 풍습 중 하나가 두레(계)인데 지방마다 조금씩 다른 이름이나 다른 방식으로 이어져 왔다. ‘항두계’는 ○○○, 함경도 일대에 있어온 농사를 위한 공동생활조직이다. ‘향두’라는 말의 어원은 ‘향도’(鄕徒)에서 비롯되었다는 것이 일반적인 학설이다. ‘○○○ 항○○○○’는 농사일에 마을 사람들과 함께 모여 사연들을 노래로 표현하는 연희극이다. ‘○○○○○ 놀이’는 오랜 동안 사람들의 입에서 입으로 구전심수(口傳心授)되어 내려온 민족전통의 연희이다. 연회 중에 향두꾼들이 부르는 호미소리는 향두꾼들의 봉건의식도 반영되어 있으나 농민…","a":"평안도 향두계놀이","c":"이북5도 무형유산","r":"평안남도","s":"전역","i":"http://www.khs.go.kr/unisearch/images/nondesignated_cult_prop/1669653.jpg"},{"q":"우리나라의 관모류는 선사시대부터 우리 민속의 생활속에서 발생하고 발달해 왔으며, 특히 화관과 족두리는 삼국시대 이전부터 여자의 머리 장식을 위한 관모로 발달되어 조선시대의 유물들로 전승되어 왔다. 경제적 가치 상실로 인해 관모류 단일 품목으로는 계승이 원활하지 않아 무형유산으로서의 보전이 필수적으로, 서울시는 2017년 11월 16일에 ○○○을 서울시무형유산으로 지정하였고, 박성호를 ○○○의 보유자로 인정하였으나 2020년 10월 24일 사망하였다.","a":"관모장","c":"시도무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018102609431400.jpg"},{"q":"화각공예는 쇠뿔을 얇게 갈아 뒷면에 무늬를 그려 장식하는 공예품이나 그 기술을 말하며, 화각 일을 하는 장인을 ○○○이라 일컫는다. 화각공예는 다른 나라에서 볼 수 없는 한국 공예의 고유한 특질로서, 나전칠기와 더불어 한국 목공예의 특질을 잘 보여준다. 기원은 알 수 없으나 고려의 나전칠기에 성질이 유사한 거북의 등껍질을 쓴 사례를 들어 시대를 고대로 올려보기도 하며, 조선후기 이후에는 그 자취가 확연하다. 화각은 3~5년생 황소의 뿔을 삶고 반을 갈라서 펼쳐 평평한 면을 만든 다음 뒷면이 비칠 만큼 얇게 저며 뒷면에 문양을 그리는 복채기법을 쓴다. 복채된 문양은 색…","a":"화각장","c":"시도무형유산","r":"경기도","s":"성남시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643665.gif"},{"q":"○○○○는 경기도 평택 지역에서 전승되는 노동요를 묶어 무형유산으로 지정한 것이다. 평택이 서해안과 맞닿아 있고, 넓은 농토를 포함한 지역이므로 논농사에 사용되는 농요와 바닷일에 부르는 어로요,그리고 장례의식요의 세 가지 민요들을 한데 묶어 전승하고 있다. 농요로는 모를 심을 때 부르는 모내기소리인 ‘상사소리’를 노래하는데, 이 곡은 경기도 남부에서 널리 불리는 악곡 유형이다. 논은 초벌·재벌·만물의 세 차례에 걸쳐 김을 맨다. 이 때에는 두레를 조직하여 단체로 일을 하면서 노래를 한다. 초벌(애벌)매기에서는 흙이 덩어리져 있다는 의미의 ‘얼카덩어리소리’를 노래하며,…","a":"평택민요","c":"시도무형유산","r":"경기도","s":"평택시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2023041116003501.jpg"},{"q":"한양은 조선의 수도로서 경공장의 석조기술은 고유성과 대표성을 지니며, 한양의 석조문화는 한국의 석조기술 및 조형적 미의식을 대표하는 위치에 있었다. 한양 도읍을 기점으로 축성 및 도성의 석물 제작이 필수적이었고, 석장의 기술도 더불어 발전되어 지방 및 다른 나라의 석조문화와 비교되는 창의성과 다양성을 지녔다고 할 수 있다. 이러한 석장 전통이 원활하게 지속될 수 있도록 2020년 2월 20일에 ○○○○이 세부종목인 석구조장과 석조각장으로 나누어 서울특별시무형유산로 지정되었다. 2022년 3월 24일에 김권오씨가 석구조장 보유자로, 임한빈씨가 석조각장 보유자로 인정되었…","a":"서울석장","c":"시도무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2025070913321600.jpeg"},{"q":"탈춤은 조선 전기까지 각 지방에서 행해지던 가면놀이이다. 17세기 중엽에 이르러 궁중의 관장하에 “산대”라 불리는 무대에서 상연되던 산대도감극(山臺都監劇)의 형태로, 인조 12년(1634)에 궁중에서의 상연이 폐지되자 민중에게 유입되어 전국으로 전파되었다. 황해도탈춤은 황해도의 평산과 기린의 남북을 중심으로 북쪽의 봉산탈춤형과 남쪽의 해주탈춤형으로 나눌 수 있는데, ○○○○은 해주탈춤형으로 분류된다. ○○○○은 매년 단오에 행해지는데 사자춤·말뚝이춤·목중춤·상좌춤·양반과 말뚝이춤·노승과 취발이춤·영감과 할미광대춤의 7개 과장으로 구성되어 있다. 놀이에 앞서 탈과 의상…","a":"강령탈춤","c":"국가무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623161.jpg"},{"q":"‘○○○’은 불경(佛經)을 쓰는 사경(寫經) 기술을 가진 장인을 말한다. 역사적으로 고려 시대에 불교가 성행하면서 사경이 전성기를 맞이했으며, 특히, 충렬왕 대에 중국에 수백 명의 사경승(寫經僧)을 파견하는 등 대외적으로 고려 사경의 우수성이 널리 알려졌다. 조선 시대에는 숭유억불(崇儒抑佛)의 기조가 유지되면서 쇠퇴하였으나, 일부 왕실과 사찰에 의해서 명맥이 유지되었다. 통일신라 시대 때(745~755년) 제작된 ‘신라백지묵서대방광불화엄경(국보)’은 우리나라에 현존하는 가장 오래된 사경 유물이다. 사경 제작은 크게 필사, 변상도(變相圖) 제작, 표지 장엄 세 가지로…","a":"사경장","c":"국가무형유산","r":"전북특별자치도","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/2020072111095200.png"},{"q":"○○○는 조선중기 이래로 지속된 대표적인 민족 예술의 하나로, 민족 고유의 음악과 문학을 담고 있으며, 특히 동초제(東超制) ○○○는 가사와 문학성을 중시해 사설이 정확할 뿐만 아니라 너름새(동작)가 정교하고 부침새(장단)가 다양하여 무형유산으로서 지정 가치가 있다. 아울러 ○○○○○와 관련된 예능 실현과 전승자 양성 등 보존․전승을 위하여 동 예능을 가지고 있는 고향임을 예능보유자로 인정하였다.","a":"판소리 춘향가","c":"시도무형유산","r":"대전광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018101116105900.jpg"},{"q":"○○는 성직자의 길을 걸으며 얻게 되는 번민과 고뇌를 춤으로 승화시킨 무용으로, 불교적 색채가 강하고 가사袈裟와 장삼長衫을 걸치고 고깔을 착용한 채 춤을 추기 때문에 ○○라는 이름을 얻게 되었다. 주된 춤사위가 ○○○○과 유사하며, 춤의 형태도 완벽한 독무毒霧이다. 경기도지정 무형유산 ○○는 화성 재인청才人廳의 ○○를 계승한 춤인데, 그 유래에 의하면 상좌上座가 스승의 병환을 낫게 하기 위해 ○○를 추었고 스승의 병이 낫자 절을 떠났다고 한다. 그래서 재인청류의 ○○에서는 북놀이 과장을 끝내고 고깔과 장삼을 벗어 북에 걸친 후 떠나는 춤사위가 포함되어 있다. ○○○○…","a":"승무·살풀이춤","c":"시도무형유산","r":"경기도","s":"수원시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643619.jpg"},{"q":"○○○○는 줄쌈이라고도 하며 풍년을 기원하는 농경의식의 하나로 정월 대보름에 행해졌다. 기줄은 큰 줄에 매달린 작은 줄이 마치 게의 발과 같다해서 게줄이라고도 하며, ○○○○○는 한자어로 해색전(蟹索戰)이라고도 한다. ○○○○○ 유래에 대하여는 조선 현종(재위 1659∼1674) 때 삼척지방에 저수지를 많이 만들면서 시작되었다고 하나 정확한 기록은 없다. ○○○○○는 음력 1월 1일이면 우선 어린이들이 양편으로 나뉘어 북, 꽹과리 등을 두드리며 ○○○○○를 하는데 줄이나 규모면에서 작다하여 속닥기줄이라고 한다. 차츰 규모가 커지면서 7·8일 경이면 청소년들이 주동이…","a":"삼척기줄다리기","c":"시도무형유산","r":"강원특별자치도","s":"삼척시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643720.jpg"},{"q":"조상대대로 이어온 농경문화의 집합체인 <○○○○○>는 한강과 임진강에 접해 있어 우리 나라 최초로 벼농사를 지었던 김포시 통진읍 가현리와 옹정리에서 전래되어 온 민속 예술이다. 해학과 풍자적인 내용을 많이 담고 불려 왔으나 일제의 민족 말살정책에 의하여 대부분이 전래 되지 못하고 잊혀졌다. 광복 이후 60년대 중반까지 두레(농사반)를 조직하여 농악을 울리면서 흥겹게 농사짓던 풍속이 김포 곳곳에 되살아나는 듯 했지만 산업화의 물결에 따라 대부분의 논이 경지정리가 되고 경운기, 이앙기, 트랙터 등 기계화는 물론 농약의 사용에 따라 두레나 논김매기가 자취를 감추면서 <○○…","a":"김포통진두레놀이","c":"시도무형유산","r":"경기도","s":"김포시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643655.gif"},{"q":"마을의 안녕과 풍요를 비는 동제(洞祭)의 형태는 산신제(山神祭)를 비롯하여 서낭제, 탑신제(塔神祭) 등 여러 가지가 있다. 산신제는 전국적 분포를 보이며, 서낭제는 주로 한강이북에, 탑신제는 한강이남에 분포한다. 오티 ○○○는 한강이북에 분포된 북방계의 서낭제이고 그 제의(祭儀)가 ○○○의 형식을 갖고 있다. 오티 ○○○의 유래는 명확하지 않다. 그러나 오티마을이 약 400년전에 형성되었다고 하는 것으로 보아 ○○○의 유래도 400년전으로 추정이 가능하다. 특히 오티마을의 뒷산에 봉수대가 있었고 오티마을에 봉화군이 상주했다는 역사적 배경에서 보면 오티 ○○○는 봉수대…","a":"제천 오티별신제","c":"시도무형유산","r":"충청북도","s":"제천시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643880.jpg"},{"q":"취타란 부는 악기(취악기)와 치는 악기(타악기)를 함께 연주하는 것을 말한다. ○○○는 왕의 행차나 군대의 행진 또는 개선 등에 취타와 세악(비교적 음량이 적고 실내에 알맞은 악기들로 연주하는 국악 합주)을 대규모로 연주하는 것으로, ‘무령지곡’이라고도 한다. 취고수(취타 악사)들의 행진음악은 고구려 벽화라든가 백제의 악기에 관한 기록으로 보아 삼국시대에도 있었던 것으로 보인다. 고려 때에는 음악을 연주하는 취각군이라는 군사가 있어 조선시대까지 이어졌으나, 조선 중기 이후부터 변화가 생겨 세악이 연주에 끼게 되었다. 군악수(취타와 세악을 연주하는 악사들을 합한 말)들…","a":"피리정악 및 대취타","c":"국가무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623225.jpg"},{"q":"○○이란 석조물을 제작하는 장인으로, 주로 사찰이나 궁궐 등에 남아있는 불상, 석탑, 석교 등이 이들의 작품이라 할 수 있다. 삼국시대부터 현재에 이르기까지 다양한 석조문화유산이 전해지고 있어 우리나라의 석조물 제작 기술이 상당한 수준에 이르렀음을 알 수 있다. 동양 삼국의 미술을 비교할 때 ‘중국의 벽돌, 일본의 나무, 한국의 돌’이라고들 한다. 이렇듯 양질의 석재가 각처에서 생산되는 우리나라의 경우, 석조미술이 발달하였고 불교가 성행하자 돌을 다듬어 부처의 형상을 만드는 불상 조각이 성행하게 되었다. 그 결과 석공石工은 우리 전통문화의 아이콘이 되었으며, 석불과…","a":"석장(조각)","c":"시도무형유산","r":"경기도","s":"광주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018091411161500.jpg"},{"q":"선구마을에서 해마다 음력 정월 대보름날에 아랫마을을 남편으로 윗마을을 북편으로 나누어 시작되는 ○○○는 세시풍속이며 이 지방의 민속놀이이다. 정월 대보름이 되기 며칠 전부터 각 집에서 고를 만들 짚을 모으고 어린이들은 다른 데서 훔쳐오기도 한다. 대보름날이 되면 아랫 당산에서 먼저 당산제를 지낸다. 이것은 반농 반어촌인 선구마을에 한 해 동안 풍농과 풍어를 빌며 해난사고의 방지, 마을의 번영을 기원하는 것이다. 일제강점기에 ○○○○○ 역시 완전히 없어졌다. 하지만 ○○○○○를 복원하려는 움직임은 해방 직후부터 시작됐다. 이 마을에 사는 향토문화연구가 김찬중씨의 노력으…","a":"남해선구줄끗기","c":"시도무형유산","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644536.jpg"},{"q":"○○○○인 이만희는 선조가 지다방사(知茶房事-왕의 검식관)를 지내는 등 문중이 왕실과 인연이 깊었다. 맏며느리인 그의 친정어머니로부터 혼인전까지 집안에 전통떡 등 집안에 전승되어 오는 여러 전통음식의 제조 비법을 전수 받았다. 그는 광산김씨와 혼인한 이후 40여 년간 대전에 거주하며 떡을 포함한 이바지 음식을 만들어 혼례음식 문화의 전통을 이어왔다. 그의 음식제조 기능 가운데 대표적인 백편·꿀편·싱검초편 등 ○○○은 조선시대 궁중에서는 백설기·밀설기·신감초말밀설기로 지칭 되었던 맵쌀을 주재료로 한 떡 중에서 가장 대표적인 떡의 하나였다. 『조선왕조궁중의궤(朝鮮王朝宮中…","a":"연안이씨가각색편","c":"시도무형유산","r":"대전광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018101116062500.jpg"},{"q":"‘○○○○○’은 경상북도 김천시 개령면 광천리 빗내마을에서 전승되는 농악으로 경상북도 내륙지역 농악의 성격과 특징을 지니고 있다. 특히 ○○○○○은 양손으로 치는 대(大)북놀음이 웅장하고, 판굿(영풍굿, 영산다드래기)에서 드러나는 군사진(軍事陣) 굿이 두드러진다.","a":"김천금릉빗내농악","c":"국가무형유산","r":"경상북도","s":"김천시","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/2019090314020800.JPG"},{"q":"○○○ 설이환은 국가무형문화재 제55호 ○○○인 부친 설석철옹으로부터 소목에 관한 각종 기능을 전수 받았다. 개화기와 일본의 식민을 거치면서 우리의 전통가구양식은 일본의 가구양식과 결합한 형태를 이루었으며 6.25전란을 겪으면서 이 또한 많이 사라지게 되었다. 이처럼 사라져가는 한국 전통가구의 보존과 계승을 위하여 문화재청에서는 1975년 1월 29일 국가무형문화재 제55호 ○○○을 지정하여 천상원, 송추만, 강대규, 정돈산, 설석철 등이 전수 활동을 하였다. 전라남도의 ○○○ 전수상황을 보면 화순의 송추만이 있었고 그의 제자 이정곤이 그 기능을 전수 받았으나 안타깝…","a":"소목장","c":"시도무형유산","r":"전남광주통합특별시","s":"장성군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2026040215423400.jpg"},{"q":"정악(正樂)이란 궁정이나 관아 및 풍류방(각 지방의 풍류객들이 모여서 음악을 즐기던 장소)에서 연주하던 음악으로, 우아하고 바른 음악이란 뜻이다. ○○○○은 정악을 대금으로 연주하는 것을 가리킨다. 대금은 신라 삼죽의 하나로, 삼죽(三竹)이란 대금, 중금, 소금을 말하며, 이름 그대로 가로로 불게 되어 있는 관악기 중에서 가장 긴 것으로 ‘저’ 또는 ‘젓대’라고도 한다. 쌍골죽(雙骨竹)이라는 속이 찬 대나무 밑둥으로 만드는데, 왼쪽은 막혀 있고, 위 첫마디에 입김을 불어넣는 구멍이 있다. 그 조금 아래에는 갈대 속으로 만든 얇은 청을 대는 청구멍이 있고 다시 그 아래…","a":"대금정악","c":"국가무형유산","r":"서울특별시","s":"은평구","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623158.jpg"},{"q":"○○○○○은 남도 특유 무속 전통을 잘 전승하고 있으며 보유자 김명례는 세습 무계에서 태어나 무계 출신 남편을 만나 가업으로 전승하고 있고, ○○○○○에 대한 체계적 지식과 예능을 보유하고 있어 민속적, 예술적 가치가 크다. 씻김굿은 전라도 지역에서는 망자의 천도를 위한 굿을 씻김굿이라고 한다. 씻김굿하면 무형유산으로 지정되어 있는 진도씻김굿을 생각할 수 있으나, 전라도 지역에서는 해안과 육지 어디에서든 다양한 씻김굿이 전승되었다. 전라남도에서는 영광, 신안, 진도, 순천, 화순 등 각지에서 세습무가들이 단골판을 형성하였고, 전북특별자치도에서도 군산, 정읍, 전주,…","a":"고흥 혼맞이굿","c":"시도무형유산","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2020052413584100.jpg"},{"q":"장도는 몸에 지니는 자그마한 칼을 말하는데 일상생활에 사용하기도 하고, 몸을 보호하기 위한 호신용으로 또는 장신구로 사용되었다. 이러한 장도를 만드는 기능과 만드는 사람을 ‘○○○’이라 한다. 특히 은을 재료로 하여 만든 것을 ‘은장도’라 부르는데, 이것은 부녀자의 정절의 표상으로 시집가는 딸에게 마련해 주는 혼수품이기도 했다. 울산은 조선시대 주요 철산지이자, 470여 년 간 경상좌병영이 있어 무기 등 군수품 생산지였기 때문에 우수한 장인이 많았다. 울산의 은장도는 섬세한 세공술과 강한 담금질로 서울에까지 알려질 정도였다. 은장도에는 용, 학, 사군자, 파초 등의…","a":"장도장","c":"시도무형유산","r":"울산광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643597.jpg"},{"q":"1955년 태어난 이은규는 유근영․이은구 등에게 사사받았다. 부안 유천리 가마터는 강진 사당리와 함께 고려시대 상감청자의 제작지로 유명한 곳으로서, 이은규는 옛 고려청자의명성 재현과 새로운 작품의 제작을 위해 노력하고 있다.","a":"사기장","c":"시도무형유산","r":"전북특별자치도","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644149.jpg"},{"q":"○○○○○는 전남 나주 샛골의 무명짜는 직녀 또는 무명짜는 일에 대한 통칭이다. 목화를 원료로 만든 무명은 조선 초기부터 화폐의 구실을 하거나 일본과의 중요한 교역품 중에 하나였다. 무명의 제작과정은 재배와 수확, 씨앗기와 솜타기, 고치말기, 실잣기, 무명날기, 베매기, 무명짜기 순으로 이루어진다. 8월 중순 목화를 타고, 볕에 말린 후 씨아틀로 씨를 빼내는 씨앗기를 한다. 솜활을 이용하여 솜을 타고, 말대로 비벼 고치를 만든다. 물레를 이용하여 실을 뽑아 가락에 감는 실잣기 후 실의 굵기에 의해 한 폭에 몇 올이 들어갈지 결정하는 무명날기를 한다. 풀먹이기 과정인…","a":"나주의 샛골나이","c":"국가무형유산","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623821.jpg"},{"q":"○○○ 이지수씨는 카톨릭 신자였던 조부께서 천주교 박해를 피해 옹기 마을에 정착후 4대째 옹기제작을 계승하고 있는데, 도고면 금산리 옹기마을은 50여 전까지만 해도 장항선 일대의 최고 옹기 제작 마을로 옹기공이 300명이 되었으나 현재는 이지수씨만이 옹기를 제작하고 있는 실정임.","a":"옹기장(아산)","c":"시도무형유산","r":"충청남도","s":"아산시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2019052217413500.jpg"},{"q":"1935년 부안에서 태어난 김봉기는 어린 시절 석암 정경태와 한마을에 살면서 ○○를 배웠으며, 이후 전북특별자치도 무형유산 고민순으로 부터도 사사받았다. 김봉기는 청이 맑고 고요할 뿐 아니라 고음 처리에도 끊길 듯 하면서도 끊기지 않고 구슬이 굴러가듯 유연하게 소리를 이어가는 느낌이 특징이다. 김봉기는 전주전국남여시조경영대회, 전국남여시조경창대회 등 다수 대회에서 입상하였다.","a":"가사","c":"시도무형유산","r":"전북특별자치도","s":"부안군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644154.jpg"},{"q":"○○○○○는 주로 전라남도 일대(현재의 ○○광역시 남구 대촌동 ○○마을)에서 정월 대보름 전후에 행해지는 격렬한 남성집단놀이이다. 고싸움의 고란 옷고름, 고맺음, 고풀이 등의 예에서 보듯이 노끈의 한 가닥을 길게 늘여 둥그런 모양으로 맺은 것을 말하며, 2개의 고가 서로 맞붙어 싸움을 벌인다 해서 고싸움이라 부르는 것으로 추측된다. 고줄은 줄머리에 둥근 고를 만들어 세우고 단단하게 하기 위해서 대목을 속에 넣어 팔뚝만한 동아줄로 칭칭 감아 고줄이 빳빳하도록 하고, 둥글게 구부려 묶어서 고몸체를 만든다. 고몸체도 단단해야 하므로 큰 통나무를 속에 넣고 동아줄로 감아 곧…","a":"광주 칠석 고싸움놀이","c":"국가무형유산","r":"전남광주통합특별시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623518.jpg"},{"q":"경북 경주시 교동에 있는 최부자 집에서 대대로 빚어 온 전통있는 술이다. ○○○○○를 처음 만든 사람은 최국선으로, 그는 조선 숙종(재위 1674∼1720) 때 궁중음식을 관장하는 사옹원(司饔院)의 참봉을 지냈다고 한다. 법주를 만들 때에는 최씨 집안 마당의 우물물을 쓰는데, 물의 양과 온도가 사계절 내내 거의 일정하며 옛부터 물맛이 좋기로 이름이 나 있다. 술을 빚을 때는 이 물을 일단 팔팔 끓인 다음 식혀서 사용한다. 법주의 주원료는 토종 찹쌀이고 물과 누룩과 쌀로 빚어지는 순수한 곡주로서, 색은 밝고 투명한 미황색을 띠며, 곡주 특유의 향기와 단맛, 약간의 신맛…","a":"경주교동법주","c":"국가무형유산","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1624025.jpg"},{"q":"○○○이란 전통음악에 쓰이는 악기를 만드는 기능 또는 그러한 기능을 가진 사람을 말한다. 고구려의 벽화 등을 통해 악기를 만드는 장인은 이미 삼국시대부터 있었을 것으로 짐작되며, 조선시대에는 궁중에 악기조성청이라는 독립된 기관을 설치하여 국가에서 필요한 악기를 제작하여 사용하였다. 현재 우리나라 국악기는 약 60∼70종으로 가야금과 거문고가 가장 대표적이다. 현악기는 울림통을 오동나무로 하고 밑판을 밤나무와 소나무 등으로 제작 하는 것이 일반적이며, 장식품의 조각은 대추나무나 흑단, 향나무 등을 많이 이용한다. 현악기 이외에도 아쟁·대쟁·호금 등이 주류를 이루고 와공…","a":"악기장","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623209.jpg"},{"q":"‘○○’이란 석조물을 제작하는 장인으로, 주로 사찰이나 궁궐 등에 남아있는 불상, 석탑, 석교 등이 이들의 작품이라 할 수 있다. 삼국시대부터 오늘에 이르기까지 다양하고 다채로운 석조문화유산이 전해지고 있어 우리나라의 석조물 제작 기술이 상당한 수준에 이르렀음을 알 수 있다. 석공예의 재료는 전국적으로 가장 많이 분포되어 있는 화강암을 비롯하여 납석과 청석, 대리석 등이 활용되고 있다. 전통적인 ○○들은 망치, 정 등 수공구를 사용하여 돌이라는 단단한 물질에 생명력을 불어넣어 수준 높은 석조문화를 탄생시키고 발전시켜왔다.","a":"석장","c":"국가무형유산","r":"경기도","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623626.jpg"},{"q":"○○○○○는 살아서(生前) 미리(預) 덕을 닦는(修) 재(齋)라는 의미로, 망자를 위한 천도 의식인 영산재나 수륙재와 달리 살아있는 자가 사후의 극락왕생을 기원하는 불교의례다. ‘○○○○○’는 『동국세시기』에 19세기 중반 윤달의 대표적인 풍습으로 언급되고 있으며, (사)○○○○○보존회에 의해 범패와 작법, 장엄 등이 아울러 전승되고 있다.","a":"봉은사 생전예수재","c":"국가무형유산","r":"서울특별시","s":"강남구","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/2025110313054100.jpg"},{"q":"○○○○는 진주지방에 전승되는 여성검무로서 검기무 또는 칼춤이라고도 하며 대궐안 잔치 때 행하던 춤의 하나이다. 유래는 정확히 알 수 없으나, 신라사람들이 나라를 위해 죽은 소년을 애도하는 의미에서 춤을 추었다는 설과 논개의 얼을 달래기 위해 진주기생들이 칼춤을 춘데서 비롯되었다는 설이 있다. ○○○○는 도드리장단, 느린타령, 빠른타령에 맞추어 조선시대 무사복을 갖춘 8명의 무용수가 2줄로 마주보고 서서 양손에 색동천을 끼고 칼을 휘저으며 춘다. 춤사위의 종류로는 한삼을 끼고 무릎을 굽혀 도는 숙은사위, 앉아서 추는 앉은사위, 허리를 앞으로 엎쳤다가 뒤로 제치며 빙빙…","a":"진주검무","c":"국가무형유산","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1624093.jpg"},{"q":"○○○○는 안동지방의 이름난 집에서 전수되어 오던 증류식 소주로, 일반 백성들은 ○○○○를 상처, 배앓이, 식욕부진, 소화불량 등에 구급처방으로 활용하기도 했다고 한다. 만드는 방법은 쌀, 보리, 조, 수수, 콩 등 다섯가지 곡물을 물에 불린 후 시루에 쪄서 여기에다 누룩을 섞어 10일 가량 발효시켜 진술을 만든다. 이 진술을 솥에 담고 그 위에 소주고리를 얹어 불을 지피면 진술이 증류되어 소주가 만들어진다. 목성산의 맑은 물이 좋아 이곳에서 생산되는 ○○○○는 그 맛과 향이 뛰어나다. ○○○○는 가양주로 전승되어 오다 1920년 안동시에 공장을 세워 ‘제비원소주’라…","a":"안동소주","c":"시도무형유산","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644326.jpg"},{"q":"갓은 흑립黑笠이라고도 하며 조선시대 사대부들이 외출할 때 사용한 관모冠帽 중 하나로 신분을 반영하는 용도로 사용되었다. 입笠은 원래 햇볕이나 비와 바람을 가리기 위한 실용적인 용구로서의 쓰개였으나 재료·형태·제작법이 다양해지면서 조선시대에는 패랭이에서 초립의 단계를 거치면서 흑립이 만들어지게 되었다. 갓의 형태는 대우(모자)와 양태(갓의 테)로 이루어져 있으며, 시대에따라 모자의 높이와 양태 너비의 유행이 심하였다. 갓의 종류는 마미립馬尾笠, 저모립猪毛笠, 죽사립竹絲笠, 포립布笠, 죽저모립竹猪毛 笠, 음양립陰陽笠, 주립朱笠, 백립白笠 등이 있다. 갓을 만드는 과정은…","a":"양태장","c":"시도무형유산","r":"경기도","s":"평택시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018091413390700.jpg"},{"q":"○○○은 문방사우(文房四友)의 하나인 붓을 만드는 사람과 그 기술을 말한다. 붓은 먹을 함유하되 균일하게 발산할 수 있어야 하고, 마모에 오래 견딜 수 있는 내구력과 붓끝인 호의 갈라짐이 없어야 하고, 탄력과 유연성을 유지해야 한다. 이런 조건을 충족시킬 수 있는 재료로 양의 겨드랑이 털, 족제비 꼬리털, 산토끼털 등 여러 동물들의 털이 사용되는데, 추운 내륙지방의 짐승일수록 품질이 좋다. 붓의 구성은 촉과 붓대롱, 그리고 큰붓의 경우 붓촉과 붓대롱을 연결하는 각통으로 되어있는데, 붓대롱은 주로 대나무를 사용하고, 각통은 참죽나무를 많이 쓴다. 붓의 제작과정은 선별-…","a":"모필장","c":"시도무형유산","r":"울산광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643601.jpg"},{"q":"○○○이란 3년, 5년 혹은 10년마다 마을의 수호신인 성황(서낭)님에게 마을의 평화와 농사의 풍년을 기원하는 굿을 말한다. 경북 안동 하회마을에서는 약 500년 전부터 10년에 한번 섣달 보름날(12월 15일)이나 특별한 일이 있을 때 무진생(戊辰生) 성황님에게 ○○○을 해왔으며 굿과 더불어 성황님을 즐겁게 해드리기 위하여 ○○○를 하였다. ○○○○○는 각시의 무동마당·주지마당·백정마당·할미마당·파계승마당·양반과 선비마당·혼례마당·신방마당의 8마당으로 구성되어 있다. 놀이를 시작하기 전 대내림을 하는데, 정월 초이튿날 아침 성황당에 올라가 당방울이 달린 내림대를 잡…","a":"하회별신굿탈놀이","c":"국가무형유산","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1624009.jpg"},{"q":"○○은 칠기를 만드는 기술과 그 기능을 가진 사람을 말하며, 칠기란 목기에 옻나무에서 채취한 나무액을 칠한 용기를 말한다. 칠기를 만드는 것은 옻칠을 하는 것인데, 옻칠의 종류에는 생칠, 정제생칠, 정제칠이 있다. 생칠은 전통적인 방법으로 옻나무에서 채취한 그대로의 상태를 사용한다. 정제생칠은 생칠에 들어 있는 이물질을 제거한 칠로 약재나 용기에 바르는데 사용한다. 정제칠은 공예, 공산품에 바르기 위하여 각종 색상으로 만든 칠을 말한다. 옻칠의 성분에는 고무질이 있어 방수에 효과가 있으며, 썩지 않는 효과도 있어 예전에는 장례용 관에 거의 옻칠을 했다. 옻칠은 오래될…","a":"칠장","c":"시도무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1776117.jpg"},{"q":"수왕사에서 40년간 송화주 전통기법을 전수받아 대한민국 전통식품 명인 제1호로 지정되어 각종 전통주 품평회에서 수상하였고, 현재 전수교육을 통해 후진양성에 노력하고 있다.","a":"향토술담그기","c":"시도무형유산","r":"전북특별자치도","s":"완주군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2023062810264800.jpg"},{"q":"과하주는 수백 년 내려온 김천의 유명한 술이다. 찹쌀과 누룩을 원료로 하며, 김천시 남산동에 있는 과하천(過夏泉)의 물을 사용한다. 이 샘물로 술을 빚으면 술맛이 좋고 여름이 지나도 술맛이 변하지 않는다고 하여 과하주라는 이름이 붙었다고 한다. 다른 지방사람이 이곳에 와서 과하주 빚는 방법을 배워가서 똑같은 방법으로 아무리 빚어봐도 과하주의 맛과 향기가 나지 않는데, 그 이유는 아마도 물이 다르기 때문일 것이라고『금릉승감』에 적혀있다. 찹쌀과 누룩가루를 같은 양으로 섞어 떡을 만들고 물을 넣지않고 독에 밀봉하여 저온으로 1∼3개월 발효시켜서 만든다. 이렇게 해서 빚은…","a":"김천과하주","c":"시도무형유산","r":"경상북도","s":"김천시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644322.jpg"},{"q":"○○○은 완초를 재배한 후에 선별․가공하는 기능, 완초에 물감을 들이는 염색처리 기능, 염색 완초의 적절한 배열로 미적인 요소를 살려내는 기능까지 3단계 기능을 가지고 있는 장인(匠人)을 말한다. 완초공예품은 ‘삼국사기’에 신라 때부터 사용했다고 기록됐다. 조선시대에는 관청에서 민간에 공납을 요구하는 품목 중 하나로 왕골을 포함시켰는데 이것은 완초 공예품이 매우 귀한 물건이었음을 말해주고 있다. ○○○ 한명자 선생은 완초공예 기능인 편조법(손을 이용한 엮기법)으로 화방석, 그릇형태, 팔각형 함 등 아름다움과 쓰임새가 결합된 생활 속의 공예품으로 작품을 제작하고 완초공…","a":"완초장","c":"시도무형유산","r":"인천광역시","s":"미추홀구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2016010413553000.jpg"},{"q":"시조창은 시조시(우리나라 고유의 정형시)를 가사로 하여 노래 부르는 것을 말하며 시절가, 시절단가, 단가라고도 한다. 가장 오래된 기록은 영조(재위 1724∼1776) 때 학자 신광수의 『석북집』「관서악부」로 이세춘이 시조에 장단을 붙였다는 시가 나온다. 순조(재위 1800∼1834) 때 간행된 『유예지』와 『구라철사금자보』에서는 시조의 악보가 처음으로 나타난다. 그 후 가곡의 영향을 받아서 시조곡조가 보급됨에 따라 지역적 특징을 지니고 나뉘게 되었다. 완제시조는 전라도를 중심으로 한 시조창이다. 평시조와 사설시조가 대부분이지만 엇시조, 반사설시조 등 명확하게 구분이…","a":"완제시조창","c":"시도무형유산","r":"전남광주통합특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643542.jpg"},{"q":"조선시대 ○○지방 옹기제작과 관련하여 ]세종실록지리지] ○○목조에 '오사요리'라는 곳에 황옹을 만드는 도기소가 있었음이 기록되어 있다. 정학봉의 옹기업은 그의 고조때부터 시작된 가업으로 현재 4대째를 맞고 있다. 고조부부터 조부때까지는 ○○, 보은 일원의 옹기공장에서 일하다가 옹기업으로 명성이 높았던 부친대에 지금의 위치에 정착한 것이다. 전통적인 제작방법을 활용해 만들어진 각종 옹기는 지상위에 노출된 6칸짜리 전통 장작가마인 연실요를 통해 세상밖으로 나오게 된다. 제작품은 단지, 각종 항아리, 푼주, 자배기, 각종 반상기, 뚝배기 등 일상생활에서 쉽게 쓸 수 있는…","a":"상주 옹기장","c":"시도무형유산","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/0000000001644390.jpg"},{"q":"○○은 시조시(우리나라 고유의 정형시)에 곡을 붙여서 관현악 반주에 맞추어 부르는 우리나라 전통음악으로, ‘삭대엽(數大葉)’ 또는 ‘노래’라고도 한다. ○○의 원형은 만대엽, 중대엽, 삭대엽 순이나 느린 곡인 만대엽은 조선 영조(재위 1724∼1776) 이전에 없어졌고, 중간 빠르기의 중대엽도 조선말에는 부르지 않았던 것으로 알려져 있다. 지금의 ○○은 조선 후기부터 나타난 빠른 곡인 삭대엽에서 파생한 것으로, 가락적으로 관계가 있는 여러 곡들이 5장형식의 노래모음을 이룬 것이다. 현재 전승되고 있는 ○○은 우조, 계면조를 포함하여 남창 26곡, 여창 15곡 등 모두…","a":"가곡","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1624339.jpg"},{"q":"○○○○는 조선시대 효종9년(1658) 조세창이 설치된 곳으로서 전라도의 조세미가 해마다 모여들면서 전라도 문화가 집산된 곳이다. 해마다 ○○○○에서 마을의 안녕과 풍년을 기원하기 위한 별신제와 당산제를 성대하게 지냈는데 이때 연행되었던 것이 ○○○○○의 기원이다. ○○○○○의 특징은 가락의 엮음새가 분명할 뿐만 아니라 동·서·남·북·과 중앙의 오방위(五方位)를 상징하는 오방기(五方旗)를 축으로 오방진(五方陣)을 펼치며 화려하게 진행되며, 또한 전라 우도농악과 좌도농악 그리고 충청도 농악의 장단이 복합적으로 혼합되어있다.","a":"익산성당포구농악","c":"시도무형유산","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2023060910394401.jpg"},{"q":"하평리는 강릉농악의 한 갈래인 하평농악대가 구성되어 활동하는 전통민속마을로, ○○○○○는 해마다 좀상날(음력 2월 6일)에 주민들이 다리를 밟으며 풍년과 안녕을 기원한 행사이다. 좀상날은 좀생이별(천제 28개 별자리 중에서 ‘폴리아테스’라는 작은 별의 모임)과 달의 거리로 한해 농사의 풍흉을 점치던 날이다. 하평리에서는 좀상날이 되면 잔치를 벌이고, 홰(횃불)를 만들어 날이 어두워지면 사천진리 다리까지 가서 다리뺏기 놀이도 하였다고 한다. 다리 위에서 마을 어른이 헌관이 되어 하늘에 풍년을 기원하는 제사를 올린 다음 횃불을 들고 마을회관으로 돌아와 마당에서 횃불을 모…","a":"강릉사천하평답교놀이","c":"시도무형유산","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643748.jpg"},{"q":"○○○은 향토민요 또는 통속민요로 불리는 모든 ○○○계통 악곡으로, 한민족의 정서가 녹아 있는 노래이자 가장 널리 공유되고 있는 대표적인 문화상징 중의 하나이다. 또한, ○○○은 소박하고 자연스러운 표현으로 민중의 희로애락과 염원을 노래하고 여러 세대에 걸쳐 생명력을 더하며 전승되어옴에 따라 무형유산으로서의 역사성, 예술성, 학술성 등의 가치가 탁월하다. ※ ○○○은 전국적인 기반을 두고 지역과 세대를 초월해 광범위하게 전승되어 현대에 적용되고 있다는 점에서 특정 보유자나 보유단체를 인정하지 않는 공동체종목으로 지정하였다.","a":"아리랑","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/2016012616240700.jpg"},{"q":"<지정사유> 예천지역에서 전승되어온 ○○○○○은 하회별신굿탈놀이와 일정한 연관성을 띤다는 점에서 경북 북부의 향토성을 보이고 벽사진경을 추구하는 주술성과 상류층에 대한 풍자를 투박한 춤과 몸짓, 토속적인 가락에 실어서 전달하고 있다. 전국에서 유일하게 키로 만든 탈이 쓰인다는 점, 신령스런 동물이 부정을 물리치는 듯이 하는 동작과 춤에 커다란 부채모양의 주지판이 사용된다는 점 등에서 대단히 주목되고 가치있는 민중문화유산이다. 따라서 ○○○○○을 경상북도 무형유산으로 지정한다. 다만 공동체의식을 강조하는 종목의 특성상 개인보유자를 인정하지 않고 보존회 중심의 단체종목도…","a":"예천청단놀음","c":"시도무형유산","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018101611154300.jpg"},{"q":"<○○○○>은 치병굿뿐만 아니라 씻김굿의 마지막 절차에서 연행되는 굿놀이로서 종교적 의식으로서의 굿과, 놀이로서의 극이 혼연일체된 일인다역극의 형태로서 보기드문 민속극이이며 보유자 박경자는 전통적인 굿 예능을 보유하고 있는 무녀로서 세습무계의 전통성과 역사성뿐만 아니라 굿의 지역성과 예능성에서도 남다른 특징을 가지고 있다.","a":"순천삼설양굿","c":"시도무형유산","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644236.jpg"},{"q":"정동벌립은 농부들이 쓰는 모자의 한 종류로 제주도 고유의 것이다. 패랭이와 비슷한 모양으로 비를 피하거나 햇빛을 막기 위하여 써 왔었다. 정동벌립의 제작은 북제주군 한림읍 귀덕 1리 성로동에 집중되어 있는데, 이 정동벌립이 언제부터 만들어지기 시작했으며, 어찌하여 귀덕 1리에서만 집중적으로 전승되어 오는지는 정확히 알 수 없다. 정동벌립은 크게 절벤, 망, 천으로 나누어지는데, 이 외에도 맨처음 시작되는 가마귀방석 및 절벤과 망 사이, 망과 천 사이의 사갑바위 등이 있다. 정동벌립의 재료는 제주도 일원, 특히 산간에서 자라는 정동(댕댕이덩굴)을 쓴다. 작업공정은 크게…","a":"정동벌립장","c":"시도무형유산","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644692.jpg"},{"q":"문창제는 조선 인조 14년(1636년) 병자호란 때 순절한 충신 황시헌 공을 기리는 민속놀이로 황시헌 공의 제삿날 창원부사가 관속들과 성묘 제례하고 관기들로 하여금 추모의 춤을 추게 한 데서 비롯되었다. ○○○○○는 기능보유자 정경수 옹이 4과장으로 재현하였으며, 2003년 정경수 옹 별세 후 ○○○○○보존협회를 통해 계승되어오고 있다. 제1과장은 제향으로 황공의 위패를 세우고 제물을 진설하여 제례한다. 제2과장은 추도무로 기녀들이 소복차림에 한삼을 끼고 추도무를 추며 황공의 넋을 위로한다. 제3과장은 군노놀이로 황공이 순절할 때의 상황을 극적으로 재현한다. 제4과장…","a":"문창제놀이","c":"시도무형유산","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644436.jpg"},{"q":"농악은 원래 농부들이 두레(마을에서 공동 작업을 하기 위한 조직)를 짜서 일할 때 하는 음악으로 꽹과리, 징, 장구 북과 같은 타악기를 치며 벌이는 음악을 두루 가리키는 말이다. 호남 ○○○○은 전라남도 서부평야 지대를 중심으로 발달한 농악이며, 특히 영광지역에서 치는 농악은 영무장 농악을 바탕으로 뿌리를 두고 있다. 영무장 농악이란 영광, 무장(고창), 장성, 함평 등 이 지역에서 옛부터 전해 내려온 농악을 말하며 장성 사셨던 故,최화집(崔化集)선생님을 제1대 상쇠로 모시고 그 맥을 이어가고 있는 것이다. 농악단 편성은 대표기, 농자기(農者天下之大本) 령기(令旗),…","a":"우도농악","c":"시도무형유산","r":"전남광주통합특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644187.jpg"},{"q":"2016년 9월 22일 충청남도무형유산으로 지정되었다. 베틀은 삼베, 명주, 무명, 모시 등을 짜는 직기이다. 언제부터 만들어져 사용되었는지 정확히 알 수 없으며, 대부분이 나무로 만들어져 장기 보존이 불가능하다. 고대 직기 연구는 단편적으로 출토되는 직기의 부품, 직기그림, 직물의 분석을 통해 직기의 형태와 조작법 등을 알 수 있다. ○○ 한산모시짜기(국가지정유산·유네스코 인류무형문화유산)를 위해 반드시 필요한 것이나, 과거에 비해 모시 생산량이 급감 하면서 베틀의 수요도 감소하였다. 전통베틀의 제작기술 또한 사라질 위기에 직면하여 도지정 무형유산으로 지정하여 전통…","a":"서천 베틀장","c":"시도무형유산","r":"충청남도","s":"서천군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2020052709542300.png"},{"q":"○○○○○는 1950년대까지 북한에서 연희된 ○○○○가 넘어온 이주민속(移住民俗)의 하나로 그 원형이 현재까지도 전승되고 있는 귀중한 사례이다. ○○○○○는 정월대보름 전날부터 다음날까지 마을공동체와 함께 했던 마당놀이와 동네돌기(길놀이)를 재현하고 있다. 벽사진경의 의미와 가가호호를 순회하며 놀이를 펼치는 연희적 요소가 잘 조화 되어 있다. 속초는 실향민의 고장으로 함경도 민속문화와 언어가 중단되지 않고 계승되고, 함경남도 출신 최다 집거지인 청호동 아바이마을을 중심으로 실향민 1세와 2세대들이 합심하여 ○○○○를 전승시키고 있다.","a":"속초사자놀이","c":"시도무형유산","r":"강원특별자치도","s":"속초시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2019042111211800.jpg"},{"q":"부여 ○○○○○는 호상소리라 하는데, 호상이란 복을 누리며 오래 살던 사람이 죽은 일을 뜻한다. 호상소리가 시작된 연대는 정확히 알 수 없으나 선소리꾼인 하운(호상놀이 예능보유자)씨를 통해 오래 전부터 전해온 것으로 추정된다. ○○○○○는 진소리, 짝수소리, 두마디소리, 자진소리 등 다양하게 구성되어 있다. 이중에서 상여꾼들이 나뉘어져 서로 다른 소리를 주고받는 짝수소리가 특징이다. 상여가 나갈 때는 가장 느린 진소리를 하다가 짝수소리가 시작된다. 짝수소리는 한 소리가 끝나면 후렴을 하는 것이 아니라 다른 소리가 시작된다. 즉 주고받는 형식에 겹쳐지는 소리 부분이 있…","a":"부여용정리상여소리","c":"시도무형유산","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643997.jpg"},{"q":"소나무의 마디에 생밤과 멥쌀, 누룩을 섞어 술을 빚어 맑게 거르면 송절주가 되는데, 이것을 다시 증류하여 내리면 ○○○가 된다. ○○○의 기능보유자였던 신형철은 충남 서천군 한산면 평산 신씨 가문의 신현태씨와 이순심씨와의 사이에서 장녀로 태어났다. ○○○의 양조방법이 실린『고조리서』두 권이 친정어머니 이순심씨에게 전해내려 왔다고 하며 그 어머니 이순심씨 역시 친정에서 전해졌다고 한다. 『고조리서』두 권 가운데 한 권은 책명이『음식법』으로 1880년경에 신형철씨의 외할아버지 되는 이한수씨의 부인인 정금이씨가 지었고, 또 한 권은 16세기경에 지어진 것으로 추정되는 한글…","a":"보은 송로주","c":"시도무형유산","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643860.jpg"},{"q":"○○○○○는 경상남도 창녕군 영산면에서 대보름축제를 배경으로 전승해온 대동놀이이다. ○○○○○는 나무로 엮어 만든 소를 어깨에 메고 맞부딪쳐서 상대방의 ○○○를 쓰러뜨려 승패를 가르는 집단놀이이다. ○○○○○ 유래에 대한 정확한 기록은 남아있지 않으나 영산의 영축산과 작약산(함박산)의 형상이 마치 두 마리의 황소가 겨루고 있는 것 같다 해서 산의 나쁜 기운을 풀어주고, 불행을 막는다는 의미에서 시작되었다고 한다. ○○○○○는 일종의 편싸움 놀이로, 마을을 동·서로 갈라 두 패로 편을 짜는데 이긴 편 마을에는 풍년이 들고 진 편 마을에는 흉년이 든다고 해서 농경의식의…","a":"영산쇠머리대기","c":"국가무형유산","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1624112.jpg"},{"q":"○○○○○은 ○○○의 어촌 마을에서 마을의 수호신을 모시고 마을의 평화와 안녕, 풍요와 다산, 배를 타는 선원들의 안전을 빌기 위해 무당들을 청해다가 벌이는 대규모 굿이다. 풍어제, 풍어굿, 골매기당제라고도 하는 ○○○○○은 1년 또는 2~3년마다 열린다. 굿은 집안 대대로 굿을 해 온 세습무당이 하며, 부정굿·골맥이청좌굿·당맞이굿·화해굿·각댁성주굿·천왕굿·심청굿·손님굿·황제굿·부인곤반굿·용왕굿·꽃노래굿·대거리굿 등의 순서로 진행된다. 굿을 하는 시기는 마을마다 다르나 대체로 3∼5월, 9∼10월 사이에 주로 거행되며 굿청의 장식이 화려한데 비해 무당들이 입는 의상은…","a":"동해안별신굿","c":"국가무형유산","r":"부산광역시","s":"기장군","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623475.jpg"},{"q":"전 국가무형유산 가사 예능보유자 석암 정경태(石菴 鄭坰兌, 1916〜2004)의 ○○○법이다. 한시를 잘 지어 주역에 해박한 지식이 있었던 석암이 음양이 배합하는 율려상조법律呂相調法을 적용해 ○○○○○을 만들었다. ○○○는 전국에 널리 보급된 ○○○이다. 3〜4 음계였던 예전의 ○○○을 변경하여 선율을 재창작한 ○○○는 정경태의 시조보급 운동과 각지에서 개최된 시조경창대회를 거쳐 전국적으로 전파되었다 충청북도 무형유산 ○○○○○ 보유자 이상래는 1954년부터 부친의 ○○○을 듣고 따라 하기 시작하여 1959년 입문한 이래 정경태와 김월하,한우섭, 박인규에게 시조를 배…","a":"석암제 시조창","c":"시도무형유산","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643939.jpg"},{"q":"함안군 지역의 유구한 농경문화와 농사 일소리를 잘 담아낸 농요 “○○○○”는 함안군 지역의 유구한 농경문화와 봄, 여름, 가을 , 겨울 농사 일소리를 하나의 틀로써 구성한 작품으로 1980~90년대까지 지역 행사 프로그램의 일부분으로 일시적, 단편적으로 작품화되었던 부분들을 재검토하면서 작품을 구상하기 시작하여 “함안의 구전민요”와 함안지역 일소리 관련 서적 자료들의 취합하여 매년 정기발표회를 개최하고 있다. ○○○○는 사시사철 농작의 과정이 매우 세밀히 묘사되었으며, 기존의 농요들과 달리 빠른 작품 전개로 박진감이 넘치는 뛰어난 연출이 돋보인다.","a":"함안농요","c":"시도무형유산","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018101718220600.jpg"},{"q":"○○○○○은 금속으로 활자를 만들어서 각종 서적을 인쇄하는 장인을 말한다. 금속활자 인쇄기술은 세계에서 처음으로 고려시대에 창안되었으나 정확한 시기는 알 수 없다. 고종 19년(1232) 강화도에 천도한 고려 조정이 개경의 서적점(書籍店)에서 찍은 금속활자본 『남명천화상송증도가(南明泉和尙頌證道歌)』를 다시 새겨낸 것이 전하며, 국가전례서인 『상정예문(詳定禮文)』을 금속활자로 찍은 것으로 보아, 이 시기 이전에 금속활자 인쇄가 발달했음을 알 수 있다. 조선시대에는 중앙관서를 중심으로 단계적으로 개량·발전시켰다. 우리나라의 금속활자는 주조기법으로 제작된다. 금속활자의 제…","a":"금속활자장","c":"국가무형유산","r":"충청북도","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623681.jpg"},{"q":"벼루란 먹을 가는 돌을 말하는데 동양의 독특한 문화인 서예에 필요한 도구로 주로 4가지가 있는데 이는 문방사우 또는 문방사보(지·필·묵·연)로 불려 지며, 그 중 벼루는 먹을 갈아 먹물을 만드는 도구이다. 먹이 잘 갈리고 고유의 묵색이 잘 나타나야 하며, 바닥의 표면에는 숫돌과 같은 꺼끌꺼끌한 미세한 鋒網이 있으며 여기에 물을 붓고 먹을 마찰시킴으로써 먹물이 생기는 것이다. 이런 단순한 기능을 떠나 벼루의 여백에 조각을 하기 때문에 문양을 통해서 그 시대의 정서를 살필 수 있다. 일반적으로 벼루라면 검은 돌을 떠올리고 시중에서 흔히 대할 수 있는 남포석 벼루를 생각하…","a":"자석벼루장","c":"시도무형유산","r":"충청북도","s":"단양군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643910.jpg"},{"q":"○○은 판소리, 범패(梵唄)와 함께 한국 3대 성악곡 중의 하나이다. 시조가 대중적인 데 비해 ○○은 전문가들에 의해 계보를 따라 전승되어온 정가(正歌)로서, 남창 24곡과 여창 15곡을 ○○의 한바탕이라고 한다. 시조시를 5장 형식에 얹어서 피리·젓대·가야금·거문고·해금의 관현 반주에 맞추어 부르는데, 예술성은 시조나 가사에 비할 바가 아니다. 한국의 전통○○은 명칭상 서양의 작곡기법에 의하여 창작된 ○○과 같으나, 음악적 특징은 엄연히 구별된다. 전통○○은 16박 또는 10박의 장구장단의 반주에 의하여 연주되고, 우조(羽調)와 계면조(界面調)로 구성된다. 조선후기…","a":"가곡","c":"시도무형유산","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644397.jpg"},{"q":"○○○는 예로부터 물이 좋기로 이름난 미원지역에서 생산되는 ○○○는 함양 박씨 집안에 18대째 약 400여 년 동안 전해 내려오고 있는 술이다. 전하는 바에 따르면 충청도 도사(都事)를 지낸 박숭상이 이 마을로 낙향한 후 이 술을 빚는 비법이 전해졌다고 하며, ○○○라 함은 일찌기 신라시대에 최치원이 이 마을 앞의 신선봉에 정자를 짓고 이 술을 즐겨 마신데서 유래되었다고 한다. ○○○를 만들 때 몸에 좋은 생약제를 찹쌀·누룩 등과 함께 발효시켜 ○○ 또는 증류주(蒸溜酒)로 만드는데 마시면 변비제거에 좋고, 백발 등에 효능이 있으며, 독특한 향이 있다. 또한 마신 후에…","a":"청주 신선주","c":"시도무형유산","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643861.jpg"},{"q":"평택은 소샛들이라는 넓은 들을 끼고 있어 예로부터 농산물이 풍부하였고, 이는 ○○○○을 이루는 중요한 배경이 되었다. 또한 평택 근처의 청룡사(靑龍寺)는 일찍부터 사당패들의 근거지가 되어 조선 말기에는 그들의 농악이 크게 발달하였다. 그래서 ○○○○은 두레농악인 동시에 걸립패농악(중들이 꽹과리치면서 염불하고 동냥하는 일)의 성격을 갖는다. 농악에 사용되는 악기로는 꽹과리, 징, 북, 버꾸, 호적, 나팔이 있다. 편성은 영기수(令旗手), 농기수(農旗手), 나팔수, 호적수, 상쇠, 부쇠, 종쇠, 징수 1, 징수 2, 설장구, 부장구, 상장구, 북, 상버꾸, 부버꾸, 종버…","a":"평택농악","c":"국가무형유산","r":"경기도","s":"평택시","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623546.jpg"},{"q":"단청이란 청색, 적색, 황색, 백색, 흑색 등 다섯가지 색을 기본으로 사용하여 건축물이나 공예품 등에 무늬와 그림을 그려 아름답게 채색하는 것을 말한다. 이러한 단청을 하는 기술과 그 기술을 가진 사람을 ○○○이라고 하는데, 단청에 종사하는 사람이 승려인 경우에는 금어 또는 화승으로 불렀다. 우리나라 단청은 삼국시대의 여러 고분벽화를 통해 찾아볼 수 있는데, 특히 고구려 고분벽화는 당시의 건축양식과 단청의 모습을 보여주고 있어서 그 유래가 오래되었음을 알 수 있다. 고분에서 출토된 채화, 칠기 등의 그릇에서도 단청이 발견되나 주로 목조건축물에 많이 쓰였다. 단청은 건…","a":"단청장","c":"시도무형유산","r":"대구광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2024061015525900.jpg"},{"q":"나무로 집을 짓거나 각종 생활용품을 만드는 사람을 ‘목수(木手)’라고 하는데, 그 중 궁궐이나 사찰, 웅장한 저택 등의 건축을 담당하는 사람을 ‘○○○’이라고 하며, 난간이나 문짝 등 소규모의 목공일을 맡아하는 소목장과 구분된다. 현재 ○○○은 국가무형유산으로 그 종목이 지정되어 있으며, 3명의 보유자를 두고 있다. 그 외 충남과 전남 등의 지역에서도 시도무형유산으로 보유자를 인정하여 지역의 중요 무형유산으로 보존, 전승하고 있다. ○○○ 홍경선씨는 ○○○ 정영진-홍사구로 이어지는 전통성과 계보성을 갖추었고 전승교육의 조건 또한 마련된 것으로 인정되어 2022년1월1…","a":"대목장","c":"시도무형유산","r":"대전광역시","s":"유성구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2023041218090400.jpg"},{"q":"○○○○○는 ○○만을 중심으로 전승돼온 어로(漁撈) 노동요로 ○○만 사람들이 섬진강 하구와 남해안지역의 생태환경에 깃들어 살면서 펼쳐온 삶의 다양성을 보여주는 무형민속유산이다. 공연형태로 전하며 ○○의 구성은 노젓는○○, 그물내리는○○, 그물올리는○○, 가래질○○, 늦은○○, 도부꾼 전어 퍼주는 가래질○○, 난장굿으로 되어 있다. 남해안의 대표 어종과 연관된 ○○만 특유의 어업문화적 특징을 담고 있다.","a":"광양 진월 전어잡이 소리","c":"시도무형유산","r":"전남광주통합특별시","s":"광양시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2019052017450300.jpg"},{"q":"○○○○란 조선시대 역대 왕과 왕비의 신위를 모셔 놓은 사당(종묘)에서 지내는 제사를 가리키며, ‘대제(大祭)’라고도 부른다. 종묘는 사직과 더불어 국가존립의 근본이 되는 중요한 상징물로 정전(19실)과 영녕전(16실)이 있다. ○○○○는 정시제와 임시제로 나뉘어, 정시제는 4계절의 첫번째 달인 1월, 4월, 7월, 10월에 지냈고 임시제는 나라에 좋은 일과 나쁜 일이 있을 때 지냈으나, 해방 후부터는 5월 첫 일요일에 한번만 지내고 있다. 제사를 지내는 예법이나 예절에 있어서 모범인 의식만큼 순서와 절차는 엄격하고 장엄하게 진행된다. 제례는 크게 신을 모셔와 즐겁게…","a":"종묘제례","c":"국가무형유산","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623274.jpg"},{"q":"남도 지방은 예부터 다양하고 풍부한 농산물과 수산물을 재료로 여러 가지 음식의 조리법이 발달하였다. 특히 사람의 일생에서 거치는 각종 의례마다 특성에 맞는 음식들이 정해지고 여성들을 중심으로 전승 보급되었다. 최영자는 이연채의 가문에서 ○○○○ 기능을 전수하였고 전통 음식 ○○○○연구회를 결성하기도 했다. 폐백, 제사음식, 음청류, 조과류, 저장찬류, 한과류, 약밥, 떡, 전통주에 이르기까지 다양한 조리 기법 기능도 보유하고 있다 이애섭은 어려서는 조모와 어머니의 음식 솜씨를 익히고 호남의 명가 울산 김씨 가문에 들어가서 혼○○○, 이바지 음식 등에 그 솜씨를 발휘하…","a":"남도의례음식장","c":"시도무형유산","r":"전남광주통합특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643553.jpg"},{"q":"김무철은 부친인 김조균으로부터 ○○○을 사사받았다. 한량무 명칭은 당시 전통춤을 고수했던 전라도 지역의 특성상“남무”라 칭하였고 조선조말 남사당패 무동등이 여흥으로 추었던 춤이 남사당패가 흩어지자 기방에서 추어졌다. 한량의 한과 흥의 이미지를 복합적으로 나타낸 춤으로 갓아래로 가려진 홍안이 부채로 가리워져서 그 멋을 더하며 한량의 학식과 인격을 엿볼수 있는 춤이며, 특히 발 디딤새의 독특한 매력은 춤의 맛을 더한다.","a":"한량춤","c":"시도무형유산","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644167.jpg"},{"q":"○○○○○는 농요로서 논이나 밭에서 일을 하면서 피로를 잊고 능률을 올리기 위해 부르는 노래이다. ○○○ 또는 농사짓기 소리라고도 한다. 토속민요의 하나로 개인 또는 집단적으로 부르며, 지방에 따라서 노래가 달라질 수 있다. 구미 ○○○○○는 구미 진산동의 넓고 기름진 평야에서 일할 때 불렀던 노래이다. 이 노래의 내용에는 영남아리랑을 시작으로 나무를 하거나 풀을 벨 때 부르는 어사용, 가래질소리, 망깨소리, 목도소리가 있다. 또한 농사일을 할 때 부르던 모찌기소리, 모심기소리, 논매기소리, 타작소리가 있고, 논매기가 끝난 후에 부르는 칭칭이(쾌지나칭칭)가 있다. 구…","a":"구미발갱이들소리","c":"시도무형유산","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644394.jpg"},{"q":"우리나라에서 목화를 재배하여 무명을 짜기 시작한 것은 고려말 조선초기의 일이다. 그 기법이 이 마을에 도입된 때는 15세기경으로 전해지고 있으며, 이때부터 500여년 동안 목화재배 및 ○○○○ 기법을 오늘날까지 이어오고 있다. 제작과정은 목화재배와 수확, 씨앗기와 솜타기·고치말기·실잣기·무명날기·베매기·○○○○ 순으로 나뉜다. 씨앗기와 솜타기는 목화에서 씨를 빼내고 솜활이라는 기구를 이용해 솜을 부드럽게 만드는 과정이다. 고치말기는 솜을 말판 위에 펴놓고 말대로 비비는 과정이며, 실잣기는 물레를 이용해 실을 뽑고, 뽑은 실을 가락에 감는 단계이다. 무명날기는 실의 굵…","a":"무명짜기","c":"시도무형유산","r":"경상북도","s":"성주군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644343.jpg"},{"q":"조선 중종 11년(1516) 제6대 임금인 단종의 넋을 위로하기 위해 우승지 신상을 보내 치제한 것으로 시작되어 숙종 24년(1698) 확립된 ○○○○○는 장릉에서 올리는 유교식 제례의식으로 체계적 보존⋅전승 가치가 있을 뿐만 아니라 1791년(정조 15)에 시작된 배식단의 충신제향은 조선왕릉 중에서 유일한 것이라는 점에서 지정가치가 큼.","a":"영월 단종제례","c":"시도무형유산","r":"강원특별자치도","s":"영월군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643830.jpg"},{"q":"○○○은 목재를 소재로 나무가 가진 양감과 질감을 표현하는 조각이다. ○○○의 재료로는 결이 아름답고 견실한 오동나무, 소나무, 전나무, 은행나무, 느티나무, 회화나무 등이 많이 사용되어 왔다. 우리나라는 삼국시대때 불교가 전해지면서부터 사찰 건축과 불상 등 불교 의식과 관련된 조각들이 제작되기 시작한 것으로 보이지만 여러 차례의 전란으로 인해 대부분 소실되거나 분실되어 전하는 것은 많지 않다. ○○○의 제작과정을 살펴보면 먼저 잘 건조된 목재 위에 밑그림을 그린 뒤 목재의 필요 없는 부분을 쳐내는데 이것을 걷목이라고 한다. 점차 세부 조각을 한 뒤 완성한다. ○○○…","a":"민속목조각장","c":"시도무형유산","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2022093013384400.jpg"},{"q":"○○ 제작 도구의 성질, 내용 및 사용 방법을 잘 파악하고 있으며, 불교적 교리에 입각한 선승의 자세, 참선과 수행을 통해 ○○의 준비과정을 거치는 등 전통적인 禪風에 입각하여 작품 활동을 하고 있다. ○○ 보유자인 박만식은 선맥 계보와 ○○의 전승계보가 뚜렷하며, 선에 대한 체계적인 이론은 물론 수행 또한 겸비한 ○○승이다. 특히, ○○ 제작 과정에서 참선과 수행을 통한 선승으로서의 자질이 ○○에 적극적으로 반영되고 있는 점이 높이 평가되며, 작품의 미적 완성도가 높을 뿐만 아니라 선을 통한 운필 능력이 일정한 경지를 넘어 자유자재로 구사될 수 있다는 점 등 부산광…","a":"선화","c":"시도무형유산","r":"부산광역시","s":"수영구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643458.jpg"},{"q":"인천광역시 부평구 삼산동에 전승되는 두레농악이다. 과거에 농사일을 할 때 두레를 짜서 농사일의 신명을 돋우던 두레패 농악을 계승한 것이다.농사일 시작 전 의식 및 두레기 받기를 기원하는 당산제, 모찌기, 모심기, 김매기 등이 농사 재현, 농사일이 끝나고 호미를 씻어 걸어두는 호미걸이, 일년 농사를 모두 끝내고 당산에 가서 제사하는 당산제의 네 마당으로 구성된다.","a":"부평두레놀이","c":"시도무형유산","r":"인천광역시","s":"부평구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2016010415022300.jpg"},{"q":"농악은 농부들이 두레를 짜서 일할 때 치는 음악으로 꽹과리·징·장고·북과 같은 타악기를 치며 벌이는 음악을 두루 가리킨다. 농악을 공연하는 목적에 따라 종류를 나누어 보면 당산굿·마당밟이·걸립굿·두레굿·판굿·기우제굿·배굿 등으로 나눌 수 있고, 지역적 특징에 따라 분류하면 경기농악·영동농악·호남우도농악·호남좌도농악·경남농악·경북농악으로 갈라진다. 전라남도의 농악은 연행방식·복식·음악성 등을 기준으로 볼 때 크게 좌도굿과 우도굿, 도서해안굿으로 나눌 수 있다. 이 중 좌도굿은 전라남도 동북부 산간지대에서 발달한 농악으로, 단체놀이가 뛰어나고 빠른 가락과 동작이 주가 되…","a":"화순한천농악","c":"시도무형유산","r":"전남광주통합특별시","s":"화순군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644175.jpg"},{"q":"회촌마을을 중심으로 한 ○○○○○은 원주권과 영서 이남의 전형적인 형태의 가락과 진풀이를 가지고 있다. 가락의 종류는 모듬굿, 질굿, 긴질굿(칠채), 교환굿(품앗이장단), 덩더궁이, 자진가락, 꽃나비장단, 뚜루세 뚜루세 물구녕 뚜루세, 아랫마당 윗마당 정첨지 뱃가죽, 인사굿 등 상쇠의 가락이 다양하고 마을화합과 안녕을 기원하는 축원농악과 두레농악이 결합된 형태이다.","a":"원주매지농악","c":"시도무형유산","r":"강원특별자치도","s":"원주시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643817.jpg"},{"q":"○○○은 의례용, 신앙용으로 사용된 종이꽃을 전문적으로 만드는 장인을 말한다. 지화는 대부분 흰색이나 오색종이로 만들며 그 종류에는 궁중상화, 불교장엄화, 무속화 등이 있다. 김은옥 선생은 4대째 화공집안으로 특히 무속화를 만드는 기능을 보유하고 있으며 해달꽃, 수팔연, 칠성화, 애기씨 동자꽃, 서리화, 전발, 봉죽, 오색장발, 대신발, 함박꽃, 산신할아버지꽃, 팔선녀, 도산꽃, 꽃갓, 십장생, 송침문, 성주꽃, 액막이배 등 18종의 지화를 만들고 있다","a":"지화장","c":"시도무형유산","r":"인천광역시","s":"제물포구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2016010414594200.jpg"},{"q":"○○은 우리나라에서 오랜 기간 동안 재배, 활용되면서 이를 매개로 한 음식·의례·설화 등 관련 문화도 풍부하다. 오래 전부터 ○○은 그 효능과 희소성으로 말미암아 민간에게 불로초(不老草) 또는 만병초(萬病草)로 여겨졌으며, 이는 민간신앙, 설화 등에서 나타나고 있다. 각종 생활용품에 사용되는 ○○ 문양은 건강과 장수라는 ○○의 상징성을 보여주고 있다. 오늘날에도 몸에 이롭고 귀한 약재이자 식품이라는 ○○의 사회문화적 상징은 한국인의 정서에 깊이 뿌리내리고 있다. 이처럼 ’○○○○○‘는 ▲ 오랜 역사를 가지고 한반도 전역에서 전승되고 있다는 점, ▲ 조선 시대의 각종…","a":"인삼 재배와 약용문화","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/2020120114540600.jpg"},{"q":"○○○○이란 부녀자들이 가정에서 삼베를 이용해 직물을 짜는 과정들을 일컫는 말이다. 직물의 종류에 따라 ○○○○, 모시길쌈, 무명길쌈 등으로 나누어 부르기도 한다. 길쌈은 함경도 일부지역을 제외하고는 전국적으로 행해졌다. 이렇게 만들어진 직물은 농가의 부 소득원 중 하나였으나 화학섬유가 발달하면서 삼베 재배 농가가 줄어들어 ○○○○ 역시 사람들에게 잊혀지게 되었다. 경남 거창군은 삼국시대 이래 ○○○○의 산지로 오랜 전통을 이어왔으나, 화학섬유의 개발로 인해 자연히 쇠퇴하게 되었다. 그러함에도 불구하고 거창군 가북면 우혜리와 북상면 갈계리등 일부지역에서 삼을 재배하는…","a":"거창삼베길쌈","c":"시도무형유산","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644664.jpg"},{"q":"김시인은 어머니를 비롯한 외가계열로 5대째 전통자수를 물려 받았으며 전통자수와 인연을 가지게 된 것도 이러한 피가 연결되기 때문이 아닌가 한다. 이후 1966년 전통 자수계의 거장 김계순 선생을 만나면서 전통자수의 깊이를 알게 되어 평생을 자수와 함께 하는 계기가 되었다. 1970년 결혼 후 <홍위전통자수연구실>을 개원하고 이곳에서 주부들을 상대로 전통자수를 전수시켰으며 그동안 많은 제자들을 배출하였다. 김시인은 목기류에 자수를 접목시켜 전통 자수문화공급에 가장 앞장섰으며 기존의 병풍, 벽결이액자, 의상 등에만 수놓은 자수의 틀을 과감히 벗어났다. 스승 김계순선생으로…","a":"자수장","c":"시도무형유산","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644426.jpg"},{"q":"○○○는 남도지역을 중심으로 공동작업을 위해 조직된 두레의 한 유형이다. 두레는 20세 이상의 성년들로 구성된 대동패와 20세 이전의 청년들로 구성된 ○○○로 나눌 수 있다. ○○○는 주로 풀베기와 김매기 등의 공동노동을 하였는데, 노동의 고달픔과 지루함을 잊고 일의 능률을 높이기 위해 농악이나 춤, 노래 등을 생활화한데서 놀이가 유래하였다. ○○○○○는 아침에서 저녁까지의 하루 생활을 통하여 놀이를 행한다. 아침식사를 재촉하는 조반소고, 일터로 빨리 모이라는 모임소고, 일터로 향하는 길소고, 논을 맬 때 논매기소리 등으로 이어진다. 일을 마치고 돌아오는 길에 대동패…","a":"현천소동패놀이","c":"시도무형유산","r":"전남광주통합특별시","s":"여수시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644176.jpg"},{"q":"○○○○는 농사를 지으면서 피로를 잊고 능률을 올리기 위해 부르는 농요(農謠)로 ‘들노래’ 또는 ‘농사짓기’소리라고도 한다. 토속민요의 하나인 ○○○○는 지방에 따라서 노래가 달라질 수 있다. 강릉 ○○○○○는 이 지역을 대표하는 토속민요로, 『조선왕조실록』에 의하면 세조(재위 1455∼1468)가 ○○○○를 잘 부르는 사람을 뽑아 노래하게 하고 상을 주었다고 한다. ○○○○에 대한 의미로는 다섯 번을 꺾어 부르기 때문에 ○○○○라고 했다는 설과 ‘오’는 신성하고 고귀하다는 뜻에서, ‘○○○’는 들판을 개간한다는 뜻에서 생겼다는 설 등이 있다. 내용은 모내기소리, 김…","a":"강릉학산오독떼기","c":"시도무형유산","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643730.jpg"},{"q":"제주도는 흔히 바람과 돌과 여자가 많다고 하여 삼다도라고도 한다. 직업의 종류에 따라 여러 가지 민요도 많이 전해지고 있어 민요의 보물창고로 널리 알려져 있다. 제주도에서 불려지는 토속적인 민요와 통속적인 민요는 민요를 부르는 사람들의 직업 종류에 따라 여러 가지로 나뉘는데, 농사짓기소리, 고기잡이소리, 일할 때 부르는 소리, 의식에서 부르는 소리, 부녀요와 동요, 통속화된 잡요로 나눌 수 있다. 농사짓기소리로는 <사대소리>, <밭밟는소리>가 있고, 고기잡이소리로는 <노젓는소리>, <멸치후리는소리> 등이 있다. 일하면서 부르는 소리로는 <고래소리>, <가래질소리>,…","a":"제주민요","c":"국가무형유산","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1624232.jpg"},{"q":"○○○○○는 한산지방의 이름난 술로서 빛깔은 청주와 같다. 백제 때의 궁중술로서 백제 유민들이 나라를 잃고 그 슬픔을 잊기 위해 빚어 마셨다고 한다. 조선시대에 들어 가장 많이 알려진 술로『동국세시기』·『경도잡지』·『시의전서』·『규합총서』등에 제조법이 기록되어 있다. 소곡주를 만드는 방법은 찹쌀을 빚어 100일 동안 익힌다. 이때 며느리가 술맛을 보느라고 젓가락으로 찍어 먹다보면 저도 모르게 취하여 일어서지도 못하고 앉은뱅이처럼 엉금엉금 기어다닌다고 하여 ‘앉은뱅이술’이라고도 한다. ○○○○○는 술맛이 독특한 뛰어난 민속주로 기능보유자 우희열씨에 의해 전승되고 있다.","a":"한산소곡주","c":"시도무형유산","r":"충청남도","s":"서천군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643950.jpg"},{"q":"목재를 다루는 장인인 목수는 궁궐이나 사찰 또는 가옥을 짓는 대목장과 장롱, 문갑, 탁자, 소반 등 실내에서 사용되는 가구들과 그 외의 목공예품을 만드는 ○○○으로 구분된다. 건축상 소목은 창호와 난간, 닫집 등 건물에 부착되는 작은 시설물의 제작을 말한다. 현재 경기도 무형유산으로 지정된 김순기는 전통 창호를 전문적으로 만드는 ○○○이다. 그는 가래나무 과인 추목 또는 춘향목을 으뜸으로 치나 구하기 힘들때는 적송이나 육송 등을 사용한다. 그가 제작한 창호는 문양별로 완자창卍字窓, 세살문, 빗살문, 꽃살문 등이다. 창호 중 최고로 치는 꽃살문으로 완성된 꽃무늬 하나를…","a":"소목장(창호)","c":"시도무형유산","r":"경기도","s":"수원시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018091316425400.jpg"},{"q":"○○○○○는 서울 강동지역의 고유 민속놀이로, 쌍상여 ○○○○라고도 한다. ○○○○는 가정형편이 좋고 오래 살고 복이 있는 사람의 초상일 경우 노는 놀이로, 출상시 험난한 길을 무사히 갈 수 있도록 전날 밤 선소리꾼과 상여꾼들이 모여 빈상여를 메고 밤새도록 민가를 부르며 발을 맞추는 놀이이다. ○○○○○는 요령잽이 선소리꾼 1명이 상여 앞에서 이끌고 상여꾼 36명이 네 줄로 상여를 메는데, 10명 내외가 메는 보통 상여에 비해 대단히 큰 것이 특징이다. 상여가 집을 떠날 때는 상여를 메기 전에 요령잡기소리를 부르고, 집 떠나면서 향도가를 불러 영혼을 위로하고 생전의…","a":"바위절마을호상놀이","c":"시도무형유산","r":"서울특별시","s":"강동구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643383.jpg"},{"q":"○○○ 가운데 현악기 분야는 가야금과 거문고 등을 제작하는 장인을 일컫는다. 조선시대에는 풍류장風流匠 또는 풍물장風物匠으로도 불리었다. 현악기의 역사는 삼국시대 이전으로 거슬러 올라간다. 6현의 거문고는 고구려의 왕산악王山岳이 발명하였고, 12줄의 가야금은 가야에서 비롯하였다. 거문고는 장중한 소리에 검은 학이 모여들었다 하여 현학금玄鶴琴, 또는 가장 근본이 되는 악기라는 뜻의 현금玄琴으로도 지칭되었다. 거문고는 여흥을 넘어 유가 정치철학의 핵심인 예악禮樂 가운데 함께 어우러지는 조화의 상징으로서 사대부와 선비의 서재에도 놓이는 필수품이었다. 현악기는 거문고와 가야금…","a":"악기장(현악기)","c":"시도무형유산","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643667.jpg"},{"q":"그는 부친이 돌아가시고 14세때 소년가장이 되어 가족들의 생계를 꾸리기위하여 관음리 사점가마에서 잡일을 거들며 틈틈이 도예기술을 익혔다. 18세부터 문경지역에서 이름있는 ○○○으로 알려졌다. 1995년 대한민국 명장에 선정되고 난후 전통을 이어가는 장인으로 알려지면서 1999년부터 문경 전통찻사발축제 개최의 산파역이 되었다. 그동안 주로 해외에서 작품전시를 열었으나, 우리 전통문화에 대한 관심이 높아짐에 따라서 1980년대 이후에는 국내에서도 약 80여회 전시회를 개최하였다. 전시회의 수익금으로 도천장학회를 설립하였고, 지역봉사활동에 대부분 기부하였다. 우수한 전통도…","a":"사기장-흑유자기","c":"시도무형유산","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018010214463102.jpg"},{"q":"○○○은 고조선시대 만주지방에서 풍습으로 전해오던 것이 삼국시대 이후 성행한 것으로 전해진다. 특히 고려시대에는 국가에서 ○○○을 전담하는 응방이라는 관청을 두었고, 조선시대에는 이를 확대하여 내응방을 두었다. 일제시대 때 조선의 고유한 풍습이라 하여 금지했다가 해방 후 다시 소생했지만 현재는 거의 사라진 상태이다. 진안군 백운면 일대는 날짐승이 많고, 고원지대라서 눈이 많이 내리면 매의 먹이가 되는 꿩이 마을 가까이 몰려왔으므로 옛부터 ○○○이 성행하였다. 지금은 백운면 출신인 전영태씨가 ○○○의 전통기법을 전수받아 전통 매꾼으로서 그 명맥을 유지하고 있다.","a":"매사냥","c":"시도무형유산","r":"전북특별자치도","s":"진안군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644129.jpg"},{"q":"○○에서 전통적인 과정으로 종이를 생산했던 곳인 지소(紙所)는 안덕면 지소리와 파천면 신기리, 중평리 등 모두 세 곳이 있었다. 경상북도 ○○군 파천면 신기2리 감곡마을은 참닥나무가 많고 물이 맑아, 오래전부터 제지 마을로 알려져 왔다. 이 마을에서는 1920년대까지 20여 가구가 한지를 생산했으며, 제지를 생업으로 하지 않는 주민들도 부업으로 삼았다. 그러나 유리창의 보급으로 창호지 수요가 급격히 줄어들고, 한지를 주로 사용하던 각종 의례도 현대화되는 등, 한지 소비가 급감하여 한지 공방은 크게 위축되었다. 이처럼 어려운 상황에서도 선대 기능 보유자인 이상룡은 송강…","a":"청송 한지장","c":"시도무형유산","r":"경상북도","s":"청송군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2020022009565700.jpg"},{"q":"야류(들놀음)는 경상남도 내륙지방에서 행해지던 오광대가 바닷길을 따라 수영·동래·부산진 등에 전래된 것으로, 야류란 이름은 넓은 들판같은 곳에서 놀기 때문에 붙여진 것이라고 한다. 오광대가 전문연예인에 의해 행해진 도시가면극이라면 야류는 비직업적인 연희자들, 즉 마을사람들에 의해 토착화된 놀이이다. ○○○○는 정월 대보름 저녁에 벌어졌는데, 그 해 농사를 점치거나 풍년을 기원하는 의미로 행해졌다고 한다. 정확한 시기는 알 수 없으나, 약 100년전 인근 수영야류를 보고 시작되었다고 전해지며, 근래에는 대중오락적인 놀이로 공연되고 있다. 놀이는 문둥이춤·양반과 말뚝이의…","a":"동래야류","c":"국가무형유산","r":"부산광역시","s":"동래구","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623427.jpg"},{"q":"옥은 동양문화권에서 발달된 보석류로서 금·은과 함께 쓰여진 대표적인 보석이며, 음양오행의 다섯 가지 덕인 인(仁)·의(義)·지(智)·용(勇)·각(角)을 상징하는 장신구로 사용되었다. 또한 방위신에 예(禮)를 베푸는 예기(禮器)를 비롯하여 사회계급의 신분을 구분하는 드리개와 악기인 옥경(玉磬), 약재 및 의료용구 등 여러 가지로 사용되었다. 청동기 유적에서 발견되고 있는 옥석공예품과 삼국시대의 여러 고분에서 출토된 곱은옥, 구슬옥, 대롱옥 및 신라의 세 가지 보물 가운데 하나였던 진평왕의 옥허리띠를 통해 옥이 상류층의 중요한 장신구였음을 알 수 있다. 옥공예품은 조선시…","a":"옥장","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623963.jpg"},{"q":"한국 건축의장(建築意匠)에서 창호가 차지하는 비중은 매우 높다. 특히 궁궐건축의 경우는 벽면의 거의 대부분을 창호로 처리하는 경우가 많다. 따라서 한국의 창호는 건축의장을 결정하는 중요한 요소이며 그 종류와 크기도 다양해 고도의 기술과 기법이 필요하다. 따라서 한국전통창호의 제작을 위해서는 오랜 동안 숙련된 ○○○이 필요하다. ○○○은 소목장으로 분류하는데 대목이 건축의 구조부분을 담당한다면 소목은 수장과 장식 부분을 담당한다. ○○○은 대목이 할 수 없는 섬세함과 세밀함으로 건축의 완성도를 높이는 데 필수적인 부분을 담당하고 있다. 세밀한 이음과 맞춤, 정확한 비례…","a":"창호장","c":"시도무형유산","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643492.jpg"},{"q":"○○○○○는 죽은 이의 영혼을 극락으로 천도하는 불교의식인 영산재(靈山齋)의 뒷풀이 축제로 속칭 ‘땅설법’이라 한다. 삼회향은 『대승의장(大乘義章)』의 삼종회향(三種回向)에서 유래된 말로 자기가 닦은 선근공덕을 다른 중생에게 돌리는 중생회향, 보리회향, 실제회향을 뜻하고 ○○○○○는 불교의식에 우리나라 민속이 더해진 불교민속이다. 영산재에 참여한 모든 사람의 노고를 치하하고 각기 다른 기능을 발휘하여 조화를 이루게 한다는데, 그 즉흥성과 종합 예술인 놀이마당의 성격이 강한 행위전승의 민속이다.","a":"단양 구인사 삼회향놀이","c":"시도무형유산","r":"충청북도","s":"단양군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643937.jpg"},{"q":"한국전쟁 이후 남하한 황해도 만신들과 황해도인들에 의해 인천지역에서 전승되어 온 망자천도굿. 망자를 심판하고 저승까지 데려다 주는 시왕과 사자를 초대한 후, 가족 중의 한 명에게 대를 내리는 의식을 통해 망자가 생전에 못다한 말을 들은 후, 망자와의 작별하고 길을 갈라 망자를 저승으로 떠나보내는 의식으로 구성된다.","a":"인천자리걷이","c":"시도무형유산","r":"인천광역시","s":"남동구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2025032509334090.jpg"},{"q":"‘○○○’은 한국의 전통 목조 건축, 특히 전통 목공 기술을 가지고 있는 목수를 일컫는다. 그들의 활동 범위는 전통적인 한옥에서부터 궁궐이나 사찰과 같은 기념비적 목조 건축물에 이르는 역사적 건축물의 유지보수와 복원, 재건축에까지 이르고 있다. ○○○은 건축물의 기획·설계·시공은 물론 수하 목수들에 대한 관리 감독까지 전체 공정을 책임지는 장인이다. ○○○이 완성한 목조 구조물들은 하나같이 우아하고 간결하며 소박한데, 이런 점은 고스란히 한국 전통 건축의 고유한 특징이기도 하다. 한국의 전통적인 건축 공정에서는 건축물을 그 규모 및 입지·용도에 걸맞게 설계하는 기술적…","a":"대목장","c":"시도무형유산","r":"전남광주통합특별시","s":"광산구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643559.gif"},{"q":"갓은 조선시대 성인 남자들이 외출할 때 반드시 갖추어야 할 예복중의 하나로 원래는 햇볕, 비, 바람을 가리기 위한 실용적인 모자였으나 주로 양반의 사회적인 신분을 반영하는 용도로 사용되었다. 갓은 넓은 의미로 방갓형과 패랭이형 모두를 말하는데 일반적으로 흑립·칠립·평립이라고 부르며 ○○은 갓을 만드는 과정을 말한다. ○○은 총모자, 양태, 입자로 나뉜다. 총모자는 컵을 뒤집어 놓은 듯한 갓 대우 부분을 말꼬리털 또는 목덜미털을 사용해 만드는 것을 가리킨다. 양태는 대나무를 머리카락보다 잘게 쪼개서 레코드판처럼 둥글게 얽어내는 과정을 말하며, 입자는 총모자와 양태를 조…","a":"갓일","c":"국가무형유산","r":"기타","s":".","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1624235.jpg"},{"q":"○○○○는 땅과 곡식의 신에게 드리는 국가적인 제사로, 사(社)는 땅의 신, 직(稷)은 곡식의 신을 의미한다. 예로부터 나라를 세우면 먼저 조상에게 제사를 지내고 이와 함께 땅과 곡식의 신에게 백성이 편안하게 살 수 있도록 풍요를 기원하는 사직제를 올렸다. 삼국시대부터 행해진 사직에 대한 제사는 자연에 감사하는 우리 조상들의 마음을 엿볼 수 있다. 조선의 태조는 나라를 세우면서 궁궐과 함께 종묘, 사직단을 마련하여 경복궁의 동쪽에는 종묘를, 서쪽에는 사직단을 설치하고, 각 지방에도 사직단을 세워 백성의 편안함과 풍년을 기원하였다. 사직단은 동서로 사단((社壇:태사신과…","a":"사직대제","c":"국가무형유산","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623368.jpg"},{"q":"○○○○는 긴잡가라 하기도 하고, 좌창이라 하기도 한다. 19세기경 발생한 장르로서 사계축 소리꾼들 사이에서 만들어져 불렸다. 역사적으로 조선말기에 공예인, 상인, 기녀들이 즐겨 불렀고 사계축(四契軸:지금의 서울역에서 만리동 고개 및 청파동에 이르는 지역에 살던 남자 소리꾼들)에 의해 널리 보급되었다. 초기 ○○○○는 8잡가와 잡잡가로 구분되었는데 8잡가는 유산가, 적벽가, 제비가, 집장가, 소춘향가, 선유가, 형장가, 평양가 등이고, 잡잡가는 달거리, 십장가, 출인가, 방물가의 네 곡을 말한다. 이들을 ○○○○로 묶은 것은 12가사의 영향인 것으로 본다. 현재 부르…","a":"경기12잡가","c":"시도무형유산","r":"인천광역시","s":"미추홀구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643523.jpg"},{"q":"‘○○○’는 온 천지와 수륙에 존재하는 모든 고혼(孤魂)의 천도를 위하여 지내는 의례로 개인 천도의 성격을 띤 영산재에 비해 공익성이 두드러지는 불교 의례이다. 조선초기부터 국행 ○○○로서 대규모로 설행되어 왔던 사실이 『조선왕조실록』을 비롯한 문헌에 나타나 있다. 서울 ○○○는 조선시대에 왕실 주도의 대규모 ○○○를 주로 담당하였던 중심 사찰이었으며 의식, 설단, 장엄 등 ○○○의 여러 분야에 대한 전승이 이루어지고 있다.","a":"진관사 수륙재","c":"국가무형유산","r":"서울특별시","s":"은평구","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623663.jpg"},{"q":"북은 가죽을 통의 마구리에 메워서 이를 두드려 소리가 울리도록 만든 공명을 이용한 타악기로, 각종 의식과 전쟁의 진퇴를 알리는 신호를 위시하여 민속놀이, 창, 무용, 무속에서의 무구 등 다양하게 쓰여 왔다. 북은 통에 씌우는 가죽작업과 북통제작 등 크게 두 가지 공정으로 이루어진다. 오동, 육송, 미송, 피나무, 박달나무를 주로 사용하는 북통은 통나무를 파서 만드는 통통과 같은 크기의 쪽나무를 여러 쪽 붙여서 만드는 쪽통이 있다. 나무를 길이에 맞게 토막을 낸 후 목심부터 쪼아가면서 파 들어가 안쪽을 깎아 관통시켜 통통을 만드나, 굵은 통목을 구하기 어려워 주로 쪽통…","a":"악기장(북메우기)","c":"시도무형유산","r":"대전광역시","s":"유성구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643583.jpg"},{"q":"○○은 조선 시대 문학 장르 가운데 하나인 시조시를 5장 형식의 선율에 얹어 노래하는 악곡 양식을 말한다. 가사, 시조와 함께 정가(正歌)로 불리며, 범패, 판소리와 함께 한국의 3대 성악곡으로 꼽히기도 한다. 조선 후기 양반과 중인을 중심으로 하는 풍류객들의 대표 적인 연주악곡이었으며, 그들의 생활음악이기도 하였다.","a":"가곡(여창)","c":"시도무형유산","r":"인천광역시","s":"미추홀구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2016072116154400.jpg"},{"q":"○○○○○은 판소리가 정착한 조선 중기 이후에 생겨난 것으로 판소리에 맞추어 고수(鼓手:북치는 사람)가 북으로 장단을 쳐 반주하는 것을 말한다. 고법은 판소리의 반주이기 때문에 고수를 내세우는 일이 없어 조선시대에는 이름난 명고수가 매우 드물었다. 또한 고수를 판소리수업의 한 방편으로 여겨 고법의 발달은 미미하였다. 조선 후기에 들어 판소리가 매우 다양한 특성을 지니고 발전함에 따라 고법도 발전하나, 19세기 말에 이르러서야 전문적인 고수들이 나와 고법은 비약적인 발전을 하게 되었다. ○○○○○에는 여러가지 이론이 있으나 크게 자세론(姿勢論)·고장론(鼓長論)·연기론(…","a":"판소리고법","c":"시도무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2018102317415800.jpg"},{"q":"○○○○○노래는 내륙지방과 비교하여 일부분이 황해도(연백지방) 농요의 영향을 받았다. ○○○○○는 물고가 좁은 경우 독창으로 이어 나가다가 넓은 경우에는 두 개 이상 융두레를 설치하여 주고 받으며 노래를 한다. 또한, 모심는소리 역시 좁은 논의 경우는 독창으로 흥얼거리나 넓은 논에서는 메기고 받으며 노래한다.","a":"강화 용두레질소리","c":"시도무형유산","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643511.jpg"},{"q":"조선시대 각 지역의 관아와 민간 향연에서 가장 많이 공연되던 무용이 “검무”라는 속칭 “칼춤”이고, 그 기원은 신라 관창량에 두고 있는 만큼 천년의 역사를 가지고 있다고 할 수 있다. 각 지방에 문화와 풍토에 따라 발전되어 왔던 까닭에 각 지역에 전승되는 검무는 서로 성격을 달리하여 전승되었는데 일제시대 이후에 문화 변동으로 대부분의 검무는 전승이 끊어졌고, 지금은 경남 진주검무, 경남 통영검무, 전남 광주검무, 황해도 해주검무, 평안도 ○○○○가 전승되고 있다. 이 가운데 진주검무와 통영검무는 국가무형유산으로 지정되었다. 지금 이북에서는 전통적인 검무를 공연하지 않…","a":"평양검무","c":"이북5도 무형유산","r":"평안남도","s":"전역","i":"http://www.khs.go.kr/unisearch/images/nondesignated_cult_prop/1669629.jpg"},{"q":"삼국시대 이전부터 널리 퍼져 있었고 고려시대 이후부터는 모든 악기를 조율하는 표준악기였던 대금은 팔음 중 죽부(대나무로 만든 악기)에 속하는 공명악기이며 일명 젓대라고도 한다. 제작과정은 생대나무를 뿌리째 채취해 숯불로 연하게 구워 진을 빼고 대가 갈라지지 않게 묶은 후 1개월간 소금물에 절인다. 이후 음지에서 충분히 건조한 뒤 내공과 지공을 뚫은 후 음정을 확인하고 악기가 터지지 않도록 튼튼한 줄로 묶고 외형을 다듬어 완성한다. 80여cm 길이에 구멍은 10여개이다.","a":"대금장(일반)","c":"시도무형유산","r":"인천광역시","s":"미추홀구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2016010411425200.jpg"},{"q":"○○○이란 은으로 공예품을 만드는 기술과 그 기술을 가진 사람을 말한다. 은공예품으로는 여성들이 쓰던 노리개 및 귀걸이, 장도, 비녀, 반지 등의 장신구가 있으며, 은수저, 은주발, 대접, 폐백주전자, 은쟁반, 은구절판 등 일상생활품도 있다. 은공예품에 모양을 내는 방법으로는 은 바탕에 갖가지 색을 염색한 규사가루를 녹여 붙여 여러 가지 무늬를 나타내는 칠보와 은 위에 모양을 내며 붙이는 금부가 있다. 은공예에 쓰이는 조각기법으로는 상감과 입사가 있는데, 상감은 금속표면에 홈을 파고 은을 박아 넣는 기법이다. 입사는 금속표면을 정으로 쪼아 거칠게 하고 여기에 은을 붙…","a":"은공장","c":"시도무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643394.jpg"},{"q":"나무판에 글자나 그림을 새기는 것을 '각자'라고 하며, 각자를 하는 장인을 ○○○ 또는 각수라고 한다. 우리나라 전통 각자는 삼국시대부터 현재에 이르기까지 다양하게 전수되고 있다. 곽금원은 오옥진(국가무형문화유산) 문하에서 사사를 받은 전승자다. 전통 각자 보유기능을 40여 년 동안 연마했고, 기법과 기교가 정교하며 수준 높은 기량을 보유해 사찰 현판, 주련 등 작업한 작품이 1,000여 작품에 이른다.","a":"각자장","c":"시도무형유산","r":"전남광주통합특별시","s":"여수시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2022021511063400.JPG"},{"q":"○○○○○은 제주시 건입동의 본향당(本鄕堂)인 ○○○○에서 하는 굿이다. 건입동은 제주도의 작은 어촌으로 주민들은 물고기와 조개를 잡거나 해녀작업으로 생계를 유지하며 마을 수호신인 도원수감찰지방관(都元帥監察地方官)과 요왕해신부인(龍王海神夫人) 두 부부에게 마을의 평안과 풍요를 비는 굿을 했다. 부부수호신과 함께 영등신을 맞이하여 소중히 위하는 굿을 했는데, 영등신은 외눈백이섬 또는 강남천자국에서 2월 1일에 제주도에 들어와서 어부와 해녀들에게 풍요를 주고 2월 15일에 본국으로 돌아간다는 내방신(來訪神)이다. 당굿은 매년 음력 2월 1일과 2월 14일 하는데, 영등신…","a":"제주칠머리당영등굿","c":"국가무형유산","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1624215.jpg"},{"q":"○○는 승복을 입고 추는 춤이어서 중춤이라 하나 불교의식에서 승려가 추는 춤을 가리키는 것은 아니며, 우리나라의 대표적인 민속춤 가운데 하나이다. 유래에 대하여는 1910년대쯤 기방에서 발전되었다고 하며 불교문화사적 입장에서 본 불교설과 김만중 소설 중 구운몽에서 유래되었다는 설, 탈놀음 중에서 노장춤과 파계승의 번뇌가 낳은 춤이라는 설이 있으나 어느 것이 확실한지 단정할 수는 없다. ○○는 흰 장삼에 붉은 가사를 걸치고, 백옥같은 고깔과 버선코가 유난히 돋보이는 차림으로 염불, 도드리, 타령, 굿거리, 자진모리 등 장단의 변화에 따라 춤을 춘다. 소맷자락을 뿌리는…","a":"승무","c":"시도무형유산","r":"충청남도","s":"서산시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644012.jpg"},{"q":"탕건은 남자들이 갓을 쓸 때 받쳐 쓰는 모자의 일종으로, 사모(紗帽)나 갓 대신 평상시 집안에서 쓰며 말총이나 쇠꼬리털로 만든다. 이러한 탕건을 만드는 기술과 그 기술을 가진 사람을 ○○○이라고 한다. 조선시대에는 관직자가 평상시에 관을 대신하여 썼고, 속칭 ‘감투’라고도 하여 벼슬에 오르는 것을 일컫는 ‘감투쓴다’는 표현도 여기에서 유래되었다. 탕건은 우리나라의 말총이 대부분 제주도에서 생산되기 때문에 제주도에서 가장 많이 만들어졌다. 탕건은 홑탕건과 겹탕건, 바둑탕건으로 분류된다. 모두 형태는 같으나 겹으로 또는 2중, 3중으로 엮어 나가는 방법에 따라 모양이 달…","a":"탕건장","c":"국가무형유산","r":"제주특별자치도","s":"제주도","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1624205.jpg"},{"q":"○○○패는 조선후기 서민층에서 생겨난 민중놀이 집단으로 ○○○○와 함께 접시돌리기(버나)·재주넘기(살판)·탈놀이(덧뵈기)·줄타기(어름)·꼭두각시 놀음(덜미) 여섯가지 기예능을 곁들여 공연했던 전문연희 집단이다. 꼭두쇠 아래 4~5명의 뜬쇠, 가열, 삐리(초입자), 저승패와 등짐꾼을 포함해 40~50여명으로 구성된다. 안성시 서운면 산중에 자리한 청룡사가 ○○○패의 본거지가 되었으며 ○○○○○패의 기원은 청룡사의 후원을 받은 불당골 사당패로 볼 수있다. 안성 ○○○○○는 영기와 서낭기, 호적이 편성되고, 풍물잽이는 사물과 벅구 및 무동으로 구성된다. 풍물가락은 ‘웃다리…","a":"안성남사당풍물놀이","c":"시도무형유산","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643647.jpg"},{"q":"농악은 농부들이 두레를 짜서 일할 때 치는 음악으로 꽹과리·징·장구·북과 같은 타악기를 치며 벌이는 음악을 두루 가리키는 말이다. 굿·매구·풍장·금고·취군 등으로도 불린다. 농악을 공연하는 목적에 따라 종류를 나누어 보면 당산굿·마당밟이·걸립굿·두레굿·판굿·기우제굿·배굿 등으로 나눌 수 있고, 지역적 특징에 따라 분류하면 경기농악·영동농악·호남우도농악·호남좌도농악·경남농악·경북농악으로 갈라진다. 경북농악의 일종인 ○○○○○은 천왕기(天王旗)싸움에서 발달한 농악으로 천왕기싸움은 매년 1월 초에 천왕기를 앞세우고 마을별로 농기와 농악대가 어울려 고갯마루와 장터에서 서로…","a":"청도차산농악","c":"시도무형유산","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644288.jpg"},{"q":"농악은 농부들이 두레(마을의 공동 작업을 하기 위한 조직)를 짜서 일할 때 치는 음악으로 꽹과리·징·장구·북과 같은 타악기를 치며 벌이는 음악을 두루 가리키는 말이다. ○○○○은 마을마다 전승되어온 농악이 세습무 집단의 뛰어난 예능과 접합되어 예술적 수준이 향상된 농악이다. 게다가 1920년대에는 이 지역의 민중종교인 보천교가 농악을 종교음악으로 채택하여 뛰어난 농악예능인들을 널리 모아들여 통합시킴으로써 예술적 수준이 다시 한번 향상되었다. 그 후 ○○○○은 전북지역 뿐만 아니라 전국 각지의 농악에 큰 영향을 끼쳤다. 현재 ○○○○은 유지화, 김종수씨가 예능보유자로…","a":"정읍농악","c":"시도무형유산","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644098.jpg"},{"q":"○○은 옻나무에서 채취하는 수액을 용도에 맞게 정제하여 기물에 칠하는 장인을 일컫는다. 우리나라에서 옻이 사용된 흔적은 기원전 3세기 경까지 거슬러 올라가지만 본격적인 유물이 출토된 것은 기원전 1세기 경부터이다. 칠기는 신라시대에 들어서 더욱 발전하였고, 고려시대에 들어와서는 나전과 결합되어 나전칠기라는 새로운 기법이 등장하기도 하였다. 조선시대에는 칠이 이전 시기보다 대중화되어 많은 칠기가 제작되었다. 국가에서도 전국의 옻나무 산지를 파악하여 여기에서 생산되는 옻칠을 공납받았으며, 서울과 지방에는 칠과 관련된 장인들이 주로 관청에 소속되어 활동하였다. 나무에서 채…","a":"칠장","c":"국가무형유산","r":"경기도","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623373.jpg"},{"q":"○○은 시조시(우리나라 고유의 정형시)에 곡을 붙여서 관현악 반주에 맞추어 부르는 우리나라 전통음악으로, ‘삭대엽(數大葉)’또는 ‘노래’라고도 한다. ○○의 원형은 고려가요에서 생겨난 만대엽·중대엽·삭대엽 순이나 느린 곡인 만대엽은 조선 영조(재위 1724∼1776) 이전에 없어졌고, 중간 빠르기의 중대엽도 조선 후기에는 부르지 않았던 것으로 알려져 있다. 지금의 ○○은 조선 후기부터 나타난 빠른 곡인 삭대엽에서 발생한 것으로, 가락적으로 관계가 있는 여러 곡들이 하나의 노래모음을 이룬 것이다. ○○은 시조시 한 편을 5장형식으로 구분하여 부르는데 전주곡인 대여음과…","a":"가곡","c":"시도무형유산","r":"대구광역시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2023070514340700.jpg"},{"q":"평창 ○○○○○은 해발 700m 이상의 고원지역, 적설량 1m 이상의 산간지역에서만 볼 수 있는 겨울철 공동체 사냥을 주제로 하는 민속으로, 이 지역의 의식주, 공동체 신앙, 사냥 관행 등 ○○○○의 모습을 그대로 간직하고 있으며, 특히 사냥 방법, 사냥도구 제작, 사냥제 등 강원특별자치도 산간지역의 전통적 산간 수렵문화를 잘 재현하고 있는 ○○○○이라는 점에서 전통문화의 체계적인 보존·전승을 위해 지정가치가 큼.","a":"평창황병산사냥민속","c":"시도무형유산","r":"강원특별자치도","s":"평창군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643823.jpg"},{"q":"○○○○○는 조선 전기 궁중에서 악귀를 쫓기 위해 베풀던 의식 다음에 학무와 ○○○무를 연이어 공연하는 종합적인 춤을 말한다. ○○○○○는 학모습의 탈을 쓰고 추는 학무와 연꽃에서 동기(童妓)가 태어나는 ○○○무로 구성된다. ○○○○○는 동물과 인간과의 교감세계를 표현한 독특한 춤으로 예술성이 높고, 내용이나 형식에 있어서 오랜 역사성과 전통성을 간직하고 있다. 학무는 임금을 송축하기 위해 학탈을 쓰고 추는 춤으로 고려때부터 궁중의례에서 행해 왔으며, 새의 탈을 쓰고 추는 춤으로는 우리나라에서 유일하다. ○○○무는 두 여자 아이가 연꽃술로 태어났다가 왕의 덕망에 감격…","a":"학연화대합설무","c":"국가무형유산","r":"서울특별시","s":"(특정 불가)","i":"http://www.khs.go.kr/unisearch/images/imp_intangible_cult_prop/1623199.jpg"},{"q":"300년동안 9대째 이어 내려온 '미력옹기'는 전통옹기의 제조법을 고집스레 지켜 일일이 손으로 직접 만들고 특히, 천연유약을 입힌다. 옹기 제조상 가장 중요한 질 좋은 점토, 천연유약 일명 잿물은 철분이 함유된 약토에 소나무를 태워 물내린 잿물을 섞어 만든다. 옹기 표면에 공기가 통할 수 있는 미세한 구멍을 만들어 주어 고추장이나 간장을 담가 해를 거듭해 저장해도 변질되거나 썩지 않으며 음식물의 맛과 신선도를 오래 유지시켜 주고, 오염물질을 없애주는 자연자정역할까지 하는 것으로 알려졌다. 특히, 이 지방 특유의 채바퀴 타래기법을 사용, 때려서 만들고 잿물에 담가 구워…","a":"옹기장","c":"시도무형유산","r":"전남광주통합특별시","s":"보성군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2369213.jpg"},{"q":"대장간은 금속[쇠]을 단야(鍛冶)하여 전통 농기구 등 각종 연장[도구]을 제작하는 곳으로, ○○○은 전통 농기구 등을 만드는 기술 또는 그 기술을 가진 사람을 말한다. 현재 대장간의 시설로는 풀무, 모루, 정, 메 등이 있으며 ○○○은 쇠의 성형,천공, 열처리[담금질] 등을 통해 각종 연장[도구]을 생산하고 있다. 1960년대 까지만 하여도 다수 존재하였던 ○○○은 현재는 산업화에 밀려 ○○○의 전통적 제작기법 및 전승에 위기를 맞고 있는데, 전통적인 ○○○ 제작기능을 이어받아 가업으로 이어오고 있다. 특히, 성형, 천공, 열처리 기술 등에 있어 전통적인 기능을 보유…","a":"대장장(홍성)","c":"시도무형유산","r":"충청남도","s":"홍성군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1644044.jpg"},{"q":"○○○○은 망자(亡者)의 영혼을 위로하여 저승으로 보내는 망자천도(亡者天道)굿을 말한다. 전국 각지에 망자천도굿이 있는데 서울에서는 이를 ○○○○이라 하며, 규모가 큰 경우는 새남굿이라 부른다. 호남에서는 씻김굿이라 칭한다. ○○○○도에서도 망자천도의례인 ○○○○이 전승되고 잇다. ○○○○○은 황해도굿, 경기굿, 서울굿과는 다른 독특한 구성 방식을 보인다. 내림장단 등이 있고 만세받이 장단도 ○○ 만세받이 장단이라 하여 황해도굿 만세받이나 서울굿 만세받이와도 다르다. ○○○○○은 14거리로 연행(演行)된다. 모든 부정을 물리는 별부정, 신령을 청배하는 부정굿, 칠성신…","a":"강화 교동 진오기굿","c":"시도무형유산","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/2019051510154200.jpg"},{"q":"옹기(甕器)는 점토와 천연잿물을 사용하여 1,200℃의 높은 온도에서 구워낸 토기로서 신석기시대부터 발달해 온 토기 제작기술의 정점이라고 할 수 있는 우리의 전통공예이다. 옹기는 질그릇(지사독, 진흙만으로 반죽해 잿물〔釉藥〕을 입히지 않고 번조(燔造)하여 광택이 없는 그릇)과 오지그릇(질그릇에 잿물을 입혀 번조하여 광택이 나고 단단한 그릇)을 총칭하는 말이었으나, 근대 이후 질그릇의 사용이 급격히 줄어들면서 오지그릇을 지칭하는 말로 바뀌게 되었다. 옹기는 찰흙을 빚어 구운 그릇으로, 미세한 구멍이 수없이 있어 공기와 습기는 통과되지만, 입자가 굵은 물분자는 통과되지…","a":"울산 옹기장","c":"시도무형유산","r":"울산광역시","s":"울주군","i":"http://www.khs.go.kr/unisearch/images/intangible_cult_prop/1643603.jpg"}]);